void solve()
{
  const ll BIG = 1e9;
  int N, K;
  cin >> N >> K;
  mcf_graph<int, ll> g(2 * N + 2);
  int s = 2 * N, t = s + 1;
  g.add_edge(s, t, N * K, BIG);
  rep(i, N) g.add_edge(s, i, K, 0);
  rep(j, N) g.add_edge(N + j, t, K, 0);

  rep(i, N) rep(j, N)
  {
    int a;
    cin >> a;
    g.add_edge(i, N + j, 1, BIG - a);
  }

  ll min_cost = g.flow(s, t, N * K).second;
  cout << (1LL * N * K * BIG - min_cost) << endl;

  vector<string> grid(N, string(N, '.'));
  auto edges = g.edges();
  for (auto e : edges)
  {
    if (e.from == s or e.to == t or e.flow == 0)
      continue;

    int i = e.from, j = e.to - N;
    grid[i][j] = 'X';
  }
  rep(i, N) cout << grid[i] << endl;
}

