void solve(long long N, long long K, std::vector<std::vector<long long>> A){
    // 0..N-1: rows
    // N..2N-1: cols
    // 2N: s
    // 2N+1: t
    mcf_graph<long long, long long> g(2*N+2);
    int s_index = 2 * N;
    int t_index = 2 * N + 1;

    // サンプルより。「K以下」だから選ばなくても OK と。
    // we can "waste" the flow
    g.add_edge(s_index, t_index, N * K, 1e9);

    for (int i = 0; i < N; i++) {
        int row_index = i;
        g.add_edge(s_index, row_index, K, 0);
        for (int j = 0; j < N; j++) {
            int col_index = N + j;
            if (i == 0) {
                g.add_edge(col_index, t_index, K, 0);
            }
            g.add_edge(row_index, col_index, 1, 1e9 - A[i][j]);
        }
    }
    auto p = g.flow(s_index, t_index, N * K);
    long long cap = p.first;
    long long cost = p.second;
    long long result = N * K * (long long)1e9 - cost;
    cout << result << endl;

    vector<string> result_map(N, string(N, '.'));
    for (auto e: g.edges()) {
        if (e.from != s_index && e.to != t_index && e.flow != 0) {
            result_map[e.from][e.to - N] = 'X';
        }
    }
    for (int i = 0; i < N; i++) {
        cout << result_map[i] << endl;
    }
}

