using Int = long long;
struct MinCostFlow {
    vector<vector<pair<int, int>>> G;
    vector<vector<int>> cap;
    MinCostFlow(int n) {
        G.resize(n);
        cap.resize(n, vector<int>(n));
    }
    void add_edge(int i, int j, int c, int a) {
        G[i].emplace_back(j, a);
        G[j].emplace_back(i, -a);
        cap[i][j] = c;
    }
    Int min_cost_flow(int s, int t) {
        Int ans = 0;
        vector<Int> dist(G.size()), prv(G.size());
        for (;;) {
            fill(begin(dist), end(dist), 1e18);
            fill(begin(prv), end(prv), -1);
            dist[s] = 0;
            for (int i = 0; i < G.size() - 1; i++) {
                for (int j = 0; j < G.size(); j++) {
                    for (auto [n, a] : G[j]) {
                        if (cap[j][n] > 0 && dist[n] > dist[j] + a) {
                            prv[n] = j;
                            dist[n] = dist[j] + a;
                        }
                    }
                }
            }
            if (dist[t] > 9e17) break;
            ans += dist[t];
            for (int a = t; prv[a] != -1; a = prv[a]) {
                cap[prv[a]][a]--;
                cap[a][prv[a]]++;
            }
        }
        return ans;
    }
};
