class min_cost_flow {		
public:

	struct edge_node {
		long long to;
		long long capacity, flow;
		long long cost;
		long long reverse_id;
	};

	long long VERYBIG = 1LL << 61;
	long long n, f, mf, totalcost;
	long long s, t;		// source and sink
	vector<vector<edge_node>> adj; 
	vector<long long> pp, ppid;

	min_cost_flow(long long nn, long long start, long long terminal) {		// initialize network with n nodes, starting from 0
		n = nn;
		s = start;
		t = terminal;

		adj.clear();
		adj.resize(nn);
	}


	void add_path(long long a, long long b, long long forward_capacity, long long backward_capacity = 0, long long forward_cost = 0, long long backward_cost = 0) {	// one directional
		long long ida = adj[a].size(), idb = adj[b].size();
		adj[a].push_back({ b, forward_capacity, 0, forward_cost, idb });
		adj[b].push_back({ a, backward_capacity, 0, backward_cost, ida });
	}

	void clear_flow() {		// reset all flow to zero from network 
		long long i;
		for (i = 0; i < n; i++) {
			for (auto p : adj[i]) p.flow = 0;
		}
	}

	void augment(long long v, long long maxflow) {
		if (v == s) {
			f = maxflow;		// external variable
		}
		else if (pp[v] != -1) {
			long long parent = pp[v], pid = ppid[v], rid = adj[parent][pid].reverse_id;
			long long available_flow = adj[parent][pid].capacity - adj[parent][pid].flow;

			if (maxflow < available_flow) augment(parent, maxflow);
			else augment(parent, available_flow); 

			adj[parent][pid].flow += f;
			adj[v][rid].flow -= f;

			totalcost += f * (adj[parent][pid].cost - adj[v][rid].cost);
		}
	}

	void solve_flow() {		// returns total cost and mf
		mf = 0;
		totalcost = 0;

		while (1) {
			long long i, j, k;
			vector<long long> dist;
			dist.assign(n, VERYBIG);
			dist[s] = 0;

			queue<long long> q;
			q.push(s);

