    };
    int n, m = 0;                   // 頂点数と辺数
    num_type inf = pow(10, 15);     // 無限大
    vector<vector<edge>> g;         // 隣接グラフ
    vector<num_type> dist, pot;     // 距離とポテンシャル
    vector<int> prevv, preve;       // 直前の頂点と辺
    set<tuple<int, int>> edge_set;  // 辺の集合
