    // コンストラクタ
    min_cost_flow(int n_temp) : n(n_temp) {
        g.assign(n, {});
        prevv.assign(n, 0);
        preve.assign(n, 0);
    }
    min_cost_flow(int n_temp,
                  vector<tuple<int, int, num_type, num_type>> g_temp)
        : n(n_temp) {
        int from, to;
