    num_type flow(int s, int t, num_type f) {
        num_type ret = 0;
        pot.assign(n, 0);
        while (f > 0) {
            // ダイクストラでposを更新
            priority_queue<tni, vector<tni>, greater<tni>> que;
            dist.assign(n, inf);
            dist[s] = 0;
