                    edge& e = g[v][i];
                    if (e.cap > 0 &&
                        dist[e.to] > dist[v] + e.cost + pot[v] - pot[e.to]) {
                        dist[e.to] = dist[v] + e.cost + pot[v] - pot[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push(tni(dist[e.to], e.to));
                    }
                }
            }
            // これ以上流せない
            if (dist[t] == inf) return -1;
            // pos_iを更新
            for (int v = 0; v < n; v++) pot[v] += dist[v];
            // s-t間最短路に沿って目一杯流す
            num_type d = f;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d, g[prevv[v]][preve[v]].cap);
            }
            f -= d;
            ret += d * pot[t];
            for (int v = t; v != s; v = prevv[v]) {
                edge& e = g[prevv[v]][preve[v]];
                e.cap -= d;
                g[v][e.rev].cap += d;
            }
        }
        return ret;
    }
    // 辺の状態を返す
    vector<vector<tuple<int, num_type, num_type>>> get_edges() {
        vector<vector<tuple<int, num_type, num_type>>> ret(n);
        int from, to;
        num_type f;
        for (int from = 0; from < n; from++) {
            for (edge temp : g[from]) {
                to = temp.to;
                if (edge_set.count(make_tuple(from, to))) {
                    ret[from].push_back(
                        make_tuple(to, g[to][temp.rev].cap, temp.cost));
                }
            }
        }
        return ret;
    }
};

