  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N, K;
  cin >> N >> K;
  //graph.add_edge(from, to, cap, cost)
  mcf_graph<ll, ll> graph(2 * N + 2);
  for (ll i = 0; i < N; ++i) {
