    ios_base::sync_with_stdio(false); cin.tie(0);
    int n, k; cin >> n >> k;
    solver.init(1 + 2 * n + 1);
    for (int i = 0 ; i < n ; i++) {
        solver.addEdge(0, 1 + i, k, 0);
        solver.addEdge(1 + n + i, 1 + n + n, k, 0);
        solver.addEdge(1 + i, 1 + n + n, INF, 0);
    }
    for (int i = 0 ; i < n ; i++) {
        for (int j = 0 ; j < n ; j++) {
            LL v; cin >> v;
            solver.addEdge(1 + i, 1 + n + j, 1, -v);
