int main() {
	int n, k; std::cin >> n >> k;
	std::vector<std::vector<long long int>> cost(n, std::vector<long long int>(n));
	for (auto& line : cost) for (auto& cell : line) std::cin >> cell;
	long long int max_cost{ 0 };
	for (const auto& line : cost) for (const auto& cell : line) max_cost = std::max(max_cost, cell);
	atcoder::mcf_graph<int, long long int> graph(n + n + 2);
	for (auto i = 0; i < n; ++i) {
		graph.add_edge(n << 1, i, k, 0);
		graph.add_edge(i + n, (n << 1) + 1, k, 0);
		for (auto j = 0; j < n; ++j) {
			graph.add_edge(i, j + n, 1, max_cost - cost[i][j]);
		}
	}
	auto copy = graph;
	const auto slope = graph.slope(n << 1, (n << 1) + 1);
	const auto last = std::lower_bound(slope.begin(), slope.end(), max_cost, [](const std::pair<int, long long int>& a, const long long int target) {return a.second < target; });
	const auto max_flow = last == slope.end() ? k * n : last->first - 1;
	std::vector<std::string> result(n, std::string(n, '.'));
	const auto flow = copy.flow(n << 1, (n << 1) + 1, max_flow);
	for (const auto e : copy.edges()) {
