		if (e.flow == 0) continue;
		const auto r = e.from;
		const auto c = e.to - n;
		result[r][c] = 'X';
	}
	std::cout << flow.first * max_cost - flow.second << '\n';
	for (const auto& line : result) {
		std::cout << line << '\n';
	}
}

