    std::vector<edge> edges() {
        int m = pos.size();
        std::vector<edge> result;
        for (int i = 0; i < m; i++) {
            result.push_back(get_edge(i));
        }
        return result;
    }
    void change_edge(int i, Cap new_cap, Cap new_flow) {
        int m = pos.size();
        assert(0 <= i && i < m);
        assert(0 <= new_flow && new_flow <= new_cap);
        auto& _e = g[pos[i].first][pos[i].second];
        auto& _re = g[_e.to][_e.rev];
        _e.cap = new_cap - new_flow;
        _re.cap = new_flow;
    }

    Cap flow(int s, int t) {
        return flow(s, t, std::numeric_limits<Cap>::max());
    }
    Cap flow(int s, int t, Cap flow_limit) {
        assert(0 <= s && s < _n);
        assert(0 <= t && t < _n);

        std::vector<int> level(_n), iter(_n);
        queue<int> que;

        auto bfs = [&]() {
            std::fill(level.begin(), level.end(), -1);
            level[s] = 0;
            queue<int>().swap(que);
            que.push(s);
            while (!que.empty()) {
                int v = que.front();
                que.pop();
                for (auto e : g[v]) {
                    if (e.cap == 0 || level[e.to] >= 0) continue;
                    level[e.to] = level[v] + 1;
                    if (e.to == t) return;
                    que.push(e.to);
                }
            }
        };
        auto dfs = [&](auto self, int v, Cap up) {
            if (v == s) return up;
            Cap res = 0;
            int level_v = level[v];
            for (int& i = iter[v]; i < g[v].size(); i++) {
                _edge& e = g[v][i];
                if (level_v <= level[e.to] || g[e.to][e.rev].cap == 0) continue;
                Cap d =
                    self(self, e.to, std::min(up - res, g[e.to][e.rev].cap));
                if (d <= 0) continue;
                g[v][i].cap += d;
                g[e.to][e.rev].cap -= d;
                res += d;
                if (res == up) break;
            }
            return res;
        };

        Cap flow = 0;
        while (flow < flow_limit) {
            bfs();
            if (level[t] == -1) break;
            std::fill(iter.begin(), iter.end(), 0);
            while (flow < flow_limit) {
                Cap f = dfs(dfs, t, flow_limit - flow);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }

    std::vector<bool> min_cut(int s) {
        std::vector<bool> visited(_n);
        queue<int> que;
        que.push(s);
        while (!que.empty()) {
            int p = que.front();
            que.pop();
            visited[p] = true;
            for (auto e : g[p]) {
                if (e.cap && !visited[e.to]) {
                    visited[e.to] = true;
                    que.push(e.to);
                }
            }
        }
        return visited;
    }

  private:
    int _n;
    struct _edge {
        int to, rev;
        Cap cap;
    };
    std::vector<std::pair<int, int>> pos;
    std::vector<std::vector<_edge>> g;
};

void solve(){
  int N,M;
  cin >> N >> M;

  vector<string> S(N);
  REP(i,N) cin >> S[i];

  max_flow<int> mf(N*M+2);
  auto f = [&](int x, int y){return x*M+y;};

  int s = N*M, t = s+1;
  REP(i,N) REP(j,M){
    if(S[i][j]=='#') continue;
    int v = f(i,j);
    if(v&1) mf.add_edge(s,v,1);
    else mf.add_edge(v,t,1);
  }

  int dx[] = {1,-1,0,0}, dy[] = {0,0,1,-1};
  REP(i,N) REP(j,M){
    if(S[i][j]=='#'||f(i,j)%2==0) continue;
    REP(k,4){
      int nx = i+dx[k], ny = j+dy[k];
      if(!range(nx,0,N)||!range(ny,0,M)||S[nx][ny]=='#') continue;
      mf.add_edge(f(i,j),f(nx,ny),1);
    }
  }

  cout << mf.flow(s,t) << endl;

  vector<string> ans = S;
  for(auto e:mf.edges()){
    if(e.from == s || e.to == t || !e.flow) continue;
    int i = e.from/M, j = e.from%M;
    int nx = e.to/M, ny = e.to%M;
    if(i==nx){
      if(j<ny) ans[i][j] = '>', ans[nx][ny] = '<';
      else ans[i][j] = '<', ans[nx][ny] = '>';
    }
    else{
      if(i<nx) ans[i][j] = 'v', ans[nx][ny] = '^';
      else ans[i][j] = '^', ans[nx][ny] = 'v';         
    }
  }

  REP(i,N) cout << ans[i] << endl;

}

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int T = 1;
  // cin >> T;

  while(T--) solve();

  return 0;
}

