// s->(i)->(j)->t というフローネットワークを考える。
// capは，s->(i)がK,(i)->(j)が1，(j)->tがK
// costは，s->(i)が0,(i)->(j)がINF-Aij,(j)->tが0
// ※Aijの総和を最大にするために(i)->(j)のcostを-Aijとし，この総和を最小にしたいが，制約0<=costに反する。
// そこで，-Aijに代えてINF-Aij>=0を用いる。
// s->tという特別な有向辺を考え，capを最大流量K*N,costをINF(=INF-0)とする。

int main() {
	const ll INF = 1'000'000'000; // 1'000'000'007;
	int N, K; cin >> N >> K;
	mcf_graph<int, ll> g(2 * N + 2);
	rep(v, N) g.add_edge(2 * N, v, K, 0);
	rep2(v, N, 2 * N) g.add_edge(v, 2 * N + 1, K, 0);
	rep(i, N) rep(j, N) {
		ll A; cin >> A;
		g.add_edge(i, N + j, 1, INF - A);
	}
	g.add_edge(2 * N, 2 * N + 1, K * N, INF);

	/*
	for (mcf_graph<int, ll>::edge e : g.edges()) {
		dbs(e.from, e.to, e.cap, e.flow, e.cost);
	}
	*/

	pair<int, ll> p = g.flow(2 * N, 2 * N + 1, K * N);
	// dbs(p.first, p.second);

	cout << K * N * INF - p.second << endl;

	vector<vector<bool>> S(N, vector<bool>(N));

	for (mcf_graph<int, ll>::edge e : g.edges()) {
		// dbs(e.from, e.to, e.cap, e.flow, e.cost);
		if (e.from == 2 * N or e.to == 2 * N + 1) continue;
		if (e.flow == 0) continue;
		S[e.from][e.to - N] = true;
	}
	rep(i, N) {
		rep(j, N) {
			cout << (S[i][j] ? 'X' : '.');
		}
		cout << endl;
	}
}

