void solve()
{
    ll N, K;
    in(N, K);
    vvll A(N, vll(N));
    for1 (h, N) {
        for1 (w, N) {
            in(A[h][w]);
        }
    }
    ll idx = 0;
    vll hi(N);
    vll wi(N);
    for1 (i, N) {
        hi[i] = idx++;
    }
    for1 (i, N) {
        wi[i] = idx++;
    }
    ll start = idx++;
    ll goal = idx++;
    atcoder::mcf_graph<ll, ll> g(idx);
    const ll big = 1'000'000'000;
    for1 (i, N) {
        g.add_edge(start, hi[i], K, 0);
        g.add_edge(wi[i], goal, K, 0);
    }
    for1 (h, N) {
        for1 (w, N) {
            g.add_edge(hi[h], wi[w], 1, big - A[h][w]);
        }
    }
    // we can "waste" the flow
    g.add_edge(start, goal, N * K, big);

    auto ret = g.flow(start, goal, N * K);
    ll cnt = ret.first;
    ll ans = ret.first * big - ret.second;
    vector<string> grid(N, string(N, '.'));
    for (auto e : g.edges()) {
        if (e.from == start || e.to == goal || e.flow == 0) continue;
        dump(e.flow, e.cost, e.cap, e.from, e.to);
        grid[e.from][e.to - N] = 'X';
    }
    print(ans);
    for1 (i, N) {
        print(grid[i]);
    }
