    int s = 2*N;
    int g = 2*N+1;

    mcf_graph<ll,ll> G = mcf_graph<ll,ll> (2*N+2);
    rep(i,0,N){
        G.add_edge(s,i,K,0);
        G.add_edge(N+i,g,K,0);
