	T now = arr[0];
	int len = arr.size();

	vector<pair<T, int>> res;
	int cnt = 0;
	rep(i, len) {
		if (arr[i] != now) {
			res.emplace_back(now, cnt);
			now = arr[i];
			cnt = 0;
		}
		cnt++;
	}

	res.push_back(mp(now, cnt));
	return res;
}


