		mcf.add_edge(2 * N, i, K, 0);
		mcf.add_edge(i + N, 2 * N + 1, K, 0);
	}

	auto mcf2 = mcf;
	auto v = mcf.slope(2 * N, 2 * N + 1);

	int nowScore = -1;
	int ansCap = 0;

	for (auto p : v) {
		int cap = p.first, cost = p.second;
		int score = -(cost - cap * maxVal);
		if (nowScore < score) {
			nowScore = score;
			ansCap = cap;
