template <class num_type> struct min_cost_flow {
    int n;
    num_type inf = pow(10, 15);
    vector<vector<tuple<int, num_type, num_type>>> g;
    min_cost_flow(int t1, vector<tuple<int, int, num_type, num_type>>& t2,
                  int indexed = 1) {
        int u, v;
        num_type w, c;
        n = t1;
        g.resize(n);
        for (tuple<int, int, num_type, num_type> t3 : t2) {
            tie(u, v, w, c) = t3;
            add_edge(u - indexed, v - indexed, w, c);
        }
    }
    void add_edge(int From, int to, num_type& cap, num_type& cost) {
        g[From].push_back(make_tuple(to, cap, cost));
        g[to].push_back(make_tuple(From, 0, -cost));
    }
    num_type bellman_ford(vector<vector<tuple<int, num_type, num_type>>>& g,
                          int& s, int& t, num_type& flow) {
        vector<num_type> dist(n, inf);
        vector<tuple<int, num_type>> prev(n, make_tuple(-1, 0));
        dist[s] = 0;
        int To, now = t, next;
        num_type cap, cost, m = inf;
        for (int i = 0; i < n; i++) {
            for (int From = 0; From < n; From++) {
                for (tuple<int, num_type, num_type> t1 : g[From]) {
                    tie(To, cap, cost) = t1;
                    if (cap) {
                        if (dist[To] > dist[From] + cost) {
                            dist[To] = dist[From] + cost;
                            prev[To] = make_tuple(From, cap);
                        }
                    }
                }
            }
        }
        while (now != s) {
            if (get<0>(prev[now]) == -1) {
                return -inf;
            } else {
                m = min(m, get<1>(prev[now]));
                now = get<0>(prev[now]);
            }
        }
        m = min(m, flow);
        now = t;
        while (now != s) {
            next = get<0>(prev[now]);
            int gnext = (int)g[next].size(), gnow = (int)g[now].size();
            for (int i = 0; i < gnext; i++) {
                tie(To, cap, cost) = g[next][i];
                if (To == now) {
                    get<1>(g[next][i]) -= m;
                    break;
                }
            }
            for (int i = 0; i < gnow; i++) {
                tie(To, cap, cost) = g[now][i];
                if (To == next) {
                    get<1>(g[now][i]) += m;
                    break;
                }
            }
            now = next;
        }
        flow -= m;
        return dist[t] * m;
    }
    // 最小費用流を計算する、なかったら-1を返す
    num_type calc_flow(int s, int t, num_type flow) {
        num_type ans = 0;
        while (flow) {
            num_type ret = bellman_ford(g, s, t, flow);
            if (ret == -inf) {
                return -1;
            } else {
                ans += ret;
            }
        }
        return ans;
    }
};

