//primal-dual
struct edge { ll to, cap, cost, rev; };

const int MAX_V = 220;
int V;
vector<edge>G[MAX_V];
ll dist[MAX_V];
ll ans = inf;
int prevv[MAX_V], preve[MAX_V];

void add_edge(int from, int to, int cap, int cost) {
	edge fe = { to,cap,cost,(int)G[to].size() };
	edge toe = { from,0,-cost,(int)G[from].size() };
	G[from].pb(fe);
	G[to].pb(toe);
}

ll min_cost_flow(int s, int t, int f) {
	ll res = 0;
	while (f > 0) {
		//Bellman-Ford
		for (int i = 0; i < V; i++)dist[i] = inf;
		dist[s] = 0;

		for (int i = 0; i < V - 1; i++) {
			for (int j = 0; j < V; j++) {
				for (int k = 0; k < G[j].size(); k++) {
					edge &e = G[j][k];
					if (dist[j] == inf)continue;
					if (e.cap > 0 && dist[e.to] > dist[j] + e.cost) {
						dist[e.to] = dist[j] + e.cost;
						prevv[e.to] = j;
						preve[e.to] = k;
					}
				}
			}
		}

		if (dist[t] == inf)return -1;

		//s-t最短路に沿って目いっぱい流す
		ll d = f;
		for (int v = t; v != s; v = prevv[v]) {
			d = min(d, G[prevv[v]][preve[v]].cap);
		}
		f -= d;
		res += d * dist[t];
		for (int v = t; v != s; v = prevv[v]) {
			edge &e = G[prevv[v]][preve[v]];
			e.cap -= d;
			G[v][e.rev].cap += d;
		}

		//答えの記録&使われているマスをチェック
		if (ans > res) {
			ans = res;
			for (int i = 0; i < 220; i++)for (int j = 0; j < 220; j++)rec[i][j] = 0;
			for (int i = 1; i <= N; i++) {
				for (int j = 0; j < G[i].size(); j++) {
					edge e = G[i][j];
					if (e.cap == 0)rec[i][e.to] = 1;
				}
			}
		}
	}
	return res;
}
