struct MinCostFlow {
  struct edge {
    int to, cap;
    int64_t cost;
    int rev;
  };
  using P = pair<int64_t, int>;
  int V;
  vector<vector<edge>> G;
  vector<int64_t> h, dist;
  vector<int> prevv, preve;
  const int64_t INF;
  MinCostFlow(int n):V(n), G(n), h(n), dist(n), prevv(n), preve(n), INF(INT64_MAX/100000) {}

  inline int add(int from, int to, int cap, int64_t cost) {
    G[from].emplace_back((edge){to, cap, cost, (int)G[to].size()});
    G[to].emplace_back((edge){from, 0, -cost, (int)G[from].size()-1});
    return G[from].size()-1;
  }
  //最小費用流//無理な時は-1
  int64_t min_cost_flow(const int s, const int t, int f) {
    int64_t res = 0;
    while(f > 0) {
      priority_queue<P, vector<P>, greater<P>> que;
      fill(dist.begin(), dist.end(), INF);
      dist[s] = 0;
      que.emplace(0, s);
      while(!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if(dist[v] < p.first) continue;
        for(int i = 0; i < G[v].size(); i++) {
          edge &e = G[v][i];
          if(e.cap > 0 and dist[e.to] > dist[v]+e.cost+h[v]-h[e.to]) {
            dist[e.to] = dist[v]+e.cost+h[v]-h[e.to];
            prevv[e.to] = v;
            preve[e.to] = i;
            que.emplace(dist[e.to], e.to);
          }
        }
      }
      if(dist[t] == INF) return -1;
      for(int v = 0; v < V; v++) h[v] += dist[v];

      int d = f;
      for(int v = t; v != s; v = prevv[v]) d = min(d, G[prevv[v]][preve[v]].cap);
      f -= d;
      res += d*h[t];
      for(int v = t; v != s; v = prevv[v]) {
        edge &e = G[prevv[v]][preve[v]];
        e.cap -= d;
        G[v][e.rev].cap += d;
      }
    }
    return res;
  }
};

