  int n, k;
  cin >> n >> k;
  vvll a(n, vll(n));
  REP(i, n) {
    REP(j, n) {
      cin >> a[i][j];
    }
  }

  mcf_graph<int, ll> flow(2 + 2 * n + n * n);

  REP(i, n) {
    flow.add_edge(0, 1 + i, k, 0);
    flow.add_edge(n * n + n + 1 + i, n * n + 2 * n + 1, k, 0);
  }

  REP(i, n) {
    REP(j, n) {
      flow.add_edge(1 + i, n + 1 + i * n + j, 1, INF - a[i][j]);
      flow.add_edge(n + 1 + i * n + j, n * n + n + 1 + j, 1, 0);
    }
  }

  vector<string> ans(n);
  REP(i, n) {
    REP(j, n) {
      ans[i] += '.';
    }
  }

  ll ma = 0;
  ll now = 0;
  REP(i, n*n) {
    pair<ll, ll> val = flow.flow(0, n * n + 2 * n + 1, 1);
    now += -val.second + (ll) INF * val.first;

    bool upd = chmax(ma, now);
    if(!upd) continue;

    auto g = flow.edges();
    REP(r, n) {
      REP(c, n) {
        ans[r][c] = '.';
      }
