    for (auto &e: g) {
      if (e.flow == 0) continue;
      if (!(1 <= e.from && e.from <= n)) continue;

      int r = (e.to - n - 1) / n, c = (e.to - n - 1) % n;
      ans[r][c] = 'X';
    }
  }

  cout << ma << endl;

  REP(i, n) {
    cout << ans[i] << endl;
  }

  return 0;
}

