template<class T>
class MinCostMaxFlow {
    // between two vertices there can only be one directed edge!!! if you want the trick with several edges between vertices,  break down
    // the edge into two pieces by introduction of new vertex
    // costs can be negative!! (capacities ofcourse not)
    public:
     struct Edge  {   int from, to;
                      T capacity, cost; };
     vector<vector<int>> adj;
     vector<vector<T>> cost, capacity;
     vector<Edge> edges;
     const ll INF = modd*modd;

     void add_edge(int fr, int tt, T cap, T cst) {
         edges.push_back({fr, tt, cap, cst});
     }

     void clear_edges() {
         edges.clear();
     }

void shortest_paths(int n, int v0, vector<T>& d, vector<T>& p) {
    d.assign(n, INF);
    d[v0] = 0;
    vector<bool> inq(n, false);
    queue<int> q;
    q.push(v0);
    p.assign(n, -1);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = false;
        for (int v : adj[u]) {
            if (capacity[u][v] > 0 && d[v] > d[u] + cost[u][v]) {
                d[v] = d[u] + cost[u][v];
                p[v] = u;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

pair<T, map<pair<int,int>,T>> min_cost_flow(int N, T K, int s, int t) {
    adj.assign(N, vector<int>());
    cost.assign(N, vector<T>(N, 0));
    capacity.assign(N, vector<T>(N, 0));
    map<pair<int,int>, T> ret;
    for (Edge e : edges) {
        adj[e.from].push_back(e.to);
        adj[e.to].push_back(e.from);
        cost[e.from][e.to] = e.cost;
        cost[e.to][e.from] = -e.cost;
        capacity[e.from][e.to] = e.capacity;
    }

    T flow = 0;
    T cost = 0;
    vector<T> d, p;
    while (flow < K) {
        shortest_paths(N, s, d, p);
        if (d[t] == INF)
            break;

        T f = K - flow;
        int cur = t;
        while (cur != s) {
            f = min(f, capacity[p[cur]][cur]);
            cur = p[cur];
        }

        // apply flow
        flow += f;
        cost += f * d[t];
        cur = t;
        while (cur != s) {
            ret[make_pair(p[cur],cur)] += f;
            capacity[p[cur]][cur] -= f;
            capacity[cur][p[cur]] += f;
            cur = p[cur];
        }
    }
    for(Edge e : edges) {
        if (set_map_includes(ret, make_pair(e.to, e.from))) {
            ret[make_pair(e.from, e.to)] -= ret[make_pair(e.to, e.from)];
            ret.erase(make_pair(e.to, e.from));
        }
    }

    if (flow < K)
        return make_pair(-1, ret);
    else
        return make_pair(cost, ret);
}
};


