using fastio::rd;
using fastio::wt;
using fastio::wtn;

void solve() {
  int N, K;
  rd(N, K);
  vvi g(N, vi(N));
  rep(i, N) rep(j, N) rd(g[i][j]);

  mcf_graph<int, ll> graph(N * 2 + 2);
  int st = N * 2, go = N * 2 + 1;

  graph.add_edge(st, go, N * K, inf);
  rep(i, N) {
    graph.add_edge(st, i, K, 0);
    graph.add_edge(i + N, go, K, 0);
  }
  rep(i, N) rep(j, N) { graph.add_edge(i, j + N, 1, inf - g[i][j]); }

  auto [fl, co] = graph.flow(st, go, N * K);
  wtn(1LL * inf * N * K - co);

  vs ans(N, string(N, '.'));
  auto es = graph.edges();
  for (auto &e : es) {
    if (e.from == st or e.to == go or e.flow == 0) continue;
    ans[e.from][e.to - N] = 'X';
  }
  rep(i, N) {
    rep(j, N) wt(ans[i][j]);
    wt('\n');
  }
}

