using namespace std;

class EMinCostFlow {

    static const int MAX = 1'000'000'000;

public:
	void solve(std::istream& in, std::ostream& out) {
        int n, k;
        in >> n >> k;
        vector<vi> A(n, vi(n));
        in >> A;
        int source = 2 * n, sink = source + 1, N = sink + 1;
        atcoder::mcf_graph<int, ll> graph(N);
        graph.add_edge(source, sink, INT_MAX, MAX);
        FOR(i, 0, n) {
            graph.add_edge(source, i, k, 0);
            graph.add_edge(n + i, sink, k, 0);
            FOR(j, 0, n) {
                graph.add_edge(i, n + j, 1, MAX - A[i][j]);
            }
        }
        int flow;
        ll cost;
        tie(flow, cost) = graph.flow(source, sink);
        cost = (ll)flow * MAX - cost;
        vector<str> res(n, str(n, '.'));
        trav(ed, graph.edges()) {
            if (ed.from != source and ed.to != sink and ed.flow) {
                res[ed.from][ed.to - n] = 'X';
            }
        }
        out << cost << '\n';
        trav(row, res) {
            out << row << '\n';
        }
	}

	void setup() {}
};


int main() {
    std::ios_base::sync_with_stdio(false);
	EMinCostFlow solver;
    solver.setup();
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
    out << std::fixed;
    out.precision(20);
	solver.solve(in, out);
	return 0;
}

