int solve() {

    SS(int, N, K);
    SVV(int, A, N, N);

    const ll MX = (ll)1e9 + 10;
    atcoder::mcf_graph<int, ll> g(2 * N + 2);
    const int S = 2 * N, T = 2 * N + 1;

    // ???
    g.add_edge(S, T, N * K, MX);

    REP (i, N) {
        g.add_edge(S, i, K, 0);      // 各行K個までしか選べない
        g.add_edge(i + N, T, K, 0);  // 各列K個までしか選べない
    }

    REP (i, N) {
        REP (j, N) {
            //     A[i][j]の和を最大化
            // -> -A[i][j]の和を最小化
            // 負辺ができるので, マージンを足して最後に消す
            g.add_edge(i, j + N, 1, MX - A[i][j]);
        }
    }

    auto [cap, cost] = g.flow(S, T, N * K);
    cost             = MX * N * K - cost;
    print(cost);

    vector<string> res(N, string(N, '.'));
    for (auto &e : g.edges()) {
        if (e.flow == 0) continue;
        if (e.from >= S) continue;
        if (e.to >= S) continue;
        res[e.from][e.to - N] = 'X';
    }
    for (auto &e : res) print(e);

    return 0;
}

