using namespace std;
typedef long long ll;

const int N_MAX = 10000;
const ll INF = 1e18;

struct edge{
    int to;
    ll cap, cost;
    int rev;
};

int V;  // 頂点数
vector<edge> G[N_MAX];
ll dist[N_MAX];
int prevv[N_MAX], preve[N_MAX];

void add_edge(int from, int to, ll cap, ll cost){
    G[from].push_back((edge){to, cap, cost, G[to].size()});
    G[to].push_back((edge){from, 0, -cost, G[from].size()-1});
}

// Vを初期化してからつかうこと
ll min_cost_flow(int s, int t, int f){
    ll res = 0;
    while(f > 0){
        fill(dist, dist+V, INF);
        dist[s] = 0;
        bool update = true;
        while(update){
            update = false;
            for(int v = 0; v < V; v++){
                if(dist[v] == INF) continue;
                for(int i = 0; i < G[v].size(); i++){
                    edge &e = G[v][i];
                    if(e.cap > 0 && dist[e.to] > dist[v]+e.cost){
                        dist[e.to] = dist[v]+e.cost;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        update = true;
                    }
                }
            }
        }
        if(dist[t] == INF){
            return -1;
        }
        ll d = f;
        for(int v = t; v != s; v = prevv[v]){
            d = min(d, G[prevv[v]][preve[v]].cap);
        }
        f -= d;
        res += d*dist[t];
        for(int v = t; v != s; v = prevv[v]){
            edge &e = G[prevv[v]][preve[v]];
            e.cap -= d;
            G[v][e.rev].cap += d;
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    int N, K;
    cin >> N >> K;
    V = (N+1)*(N+1)+2;
    ll ans = 0;
    for(int i = 1; i <= N; i++){
        add_edge(0, i, K, 0);
        add_edge(i*(N+1), (N+1)*(N+1)+1, K, 0);
        for(int j = 1; j <= N; j++){
            ll a; cin >> a;
            add_edge(i, i*(N+1)+j, 1, -a);
            add_edge(i*(N+1)+j, j*(N+1), 1, 0);
            ans += a;
        }
    }
    add_edge(0, V-1, N*K, 0);
    ll f = min_cost_flow(0, V-1, N*K);
    cout << -f << endl;
    for(int i = 1; i <= N; i++){
        for(int j = 1; j <= N; j++){
            int idx = i*(N+1)+j;
            int to = j*(N+1);
            bool used = false;
            for(auto e : G[idx]){
                if(e.to == to && e.cap == 0) used = true;
            }
            cout << (used ? 'X' : '.');
        }
        cout << endl;
    }
}

