constexpr int64 MAX_COST = 1E9;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n, k;
  cin >> n >> k;
  vector<vector<int64>> x_matrix = Make2DVector(n, n, 0LL);
  for (int r = 0; r < n; r++) {
    for (int c = 0; c < n; c++) {
      cin >> x_matrix[r][c];
    }
  }

  vector<int> row_vertex_ids(n);
  vector<int> col_vertex_ids(n);
  for (int i = 0; i < n; i++) {
    row_vertex_ids[i] = n * n + i;
    col_vertex_ids[i] = n * n + n + i;
  }
  int s = n * n + 2 * n;
  int t = n * n + 2 * n + 1;

  vector<CostFlowEdge> edges;
  for (int r = 0; r < n; r++) {
    edges.emplace_back(s, row_vertex_ids[r], k, 0);
  }
  for (int r = 0; r < n; r++) {
    for (int c = 0; c < n; c++) {
      edges.emplace_back(row_vertex_ids[r], r * n + c, 1, MAX_COST - x_matrix[r][c]);
      edges.emplace_back(r * n + c, col_vertex_ids[c], 1, 0);
    }
  }
  for (int c = 0; c < n; c++) {
    edges.emplace_back(col_vertex_ids[c], t, k, 0);
  }

  for (int r = 0; r < n; r++) {
    edges.emplace_back(row_vertex_ids[r], t, k, MAX_COST);
  }

  const auto [flow, cost, res_caps] = MinCostFlow(n * n + 2 * n + 2, edges, s, t, n * n);
  int64 value = MAX_COST * flow - cost;
  cout << value << endl;

  vector<string> output(n, string(n, '.'));
  for (int i = 0; i < edges.size(); i++) {
    if (edges[i].to < n * n) {
      if (res_caps[i] == 0) {
        int r = edges[i].to / n;
        int c = edges[i].to % n;
        output[r][c] = 'X';
      }
    }
  }

  for (int r = 0; r < n; r++) {
    cout << output[r] << endl;
  }
}

