        int A(int row, int col) => row * n + col;
        int Row(int row) => row + n * n;
        int Col(int col) => col + n + n * n;
        var source = n * n + 2 * n;
        var sink = source + 1;
        var pd = new PrimalDual(sink + 1);
        for (int i = 0; i < n; i++) {
            pd.AddEdge(source, Row(i), k, 0);
            pd.AddEdge(Col(i), sink, k, 0);
        }

        var inf = n * n * 1000000000L * 10;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                pd.AddEdge(Row(i), A(i, j), 1, inf - a[i, j]);
                pd.AddEdge(A(i, j), Col(j), 1, 0);
            }
        }

        pd.AddEdge(source, sink, n * k, inf);

        var res = pd.Run(source, sink, n * k);
        long ans = res.TotalFlow * inf - res.TotalCost;
        cout.WriteLine(ans);

        var map = E.Range(0, n).Select(_ => new StringBuilder(new string('.', n))).ToArray();

        foreach (var edge in pd.GetEdges()) {
            if (edge.To < n * n && edge.Flow == 1) {
                map[edge.To / n][edge.To % n] = 'X';
            }
        }

        for (int i = 0; i < n; i++) {
            cout.WriteLine(map[i]);
        }
    }
