public class PrimalDual {
    private readonly int N;
    private readonly List<List<Edge>> adjacents;

    private readonly Weight[] _distance;
    private readonly Weight[] _potential;
    private readonly Edge[] _prevEdges;
    private readonly PriorityQueue<Data> _queue;

    public class Edge {
        public int From, To;
        public Weight Flow, Capacity, Cost;
        public Edge Reverse;
        public Edge(int from, int to, Weight capacity, Weight cost, Weight flow = 0) {
            From = from;
            To = to;
            Cost = cost;
            Flow = flow;
            Capacity = capacity;
        }
        public Weight Residue {
            get {
                return Capacity - Flow;
            }
        }
    }

    public PrimalDual(int n) {
        N = n;
        adjacents = new List<List<Edge>>();
        for (int i = 0; i < n; i++) {
            adjacents.Add(new List<Edge>());
        }
        _distance = new Weight[N];
        _potential = new Weight[N];
        _prevEdges = new Edge[N];
        _queue = new PriorityQueue<Data>((d1, d2) => d1.Cost.CompareTo(d2.Cost));
    }

    public IEnumerable<Edge> GetEdges() {
        return adjacents.SelectMany(a => a);
    }

    public void AddEdge(int from, int to, Weight capacity, Weight cost) {
        var e = new Edge(from, to, capacity, cost);
        adjacents[from].Add(e);
    }

    struct Data {
        public int Position;
        public Weight Cost;
    }

    private Edge[] FindShortestPathTree(int source) {
        Array.Clear(_prevEdges, 0, _prevEdges.Length);
        for (int i = 0; i < N; i++) {
            _distance[i] = Weight.MaxValue;
        }
        _distance[source] = 0;
        _queue.Enqueue(new Data { Position = source, Cost = 0 });
        while (_queue.Count > 0) {
            var current = _queue.Dequeue();
            if (current.Cost > _distance[current.Position]) continue; ;
            foreach (var edge in adjacents[current.Position]) {
                if (edge.Residue > 0) {
                    var newCost = _distance[edge.From] + edge.Cost + _potential[edge.From] - _potential[edge.To];
                    if (_distance[edge.To] > newCost) {
                        _distance[edge.To] = newCost;
                        _prevEdges[edge.To] = edge;
                        _queue.Enqueue(new Data { Position = edge.To, Cost = newCost });
                    }
                }
            }
        }
        return _prevEdges;
    }

    public MinCostFlowResult Run(int source, int sink, Weight flow) {
        Weight totalCost = 0;
        Weight totalFlow = 0;

        // potential
        for (int i = 0; i < N; i++) {
            _potential[i] = Weight.MaxValue;
        }
        _potential[source] = 0;
        for (int i = 0; i < N; i++) {
            bool yet = false;
            foreach (var edge in GetEdges()) {
                if (edge.Residue > 0) {
                    var cost = _potential[edge.From];
                    if (cost == Weight.MaxValue) continue;
                    cost += edge.Cost;
                    if (_potential[edge.To] > cost) {
                        _potential[edge.To] = cost;
                        yet = true;
                    }
                }
            }
            if (!yet) break;
        }

        while (totalFlow < flow) {
            var prevEdges = FindShortestPathTree(source);
            if (prevEdges[sink] == null) {
                break;
            }

            long incrementalFlow = flow - totalFlow;
            for (var e = prevEdges[sink]; e != null; e = prevEdges[e.From]) {
                incrementalFlow = Math.Min(incrementalFlow, e.Residue);
            }
            for (var e = prevEdges[sink]; e != null; e = prevEdges[e.From]) {
                if (e.Reverse == null) {
                    var reverseEdge = new Edge(e.To, e.From, 0, -e.Cost) {
                        Reverse = e
                    };
                    e.Reverse = reverseEdge;
                    adjacents[e.To].Add(reverseEdge);
                }
                totalCost += e.Cost * incrementalFlow;
                e.Flow += incrementalFlow;
                e.Reverse.Flow -= incrementalFlow;
            }
            totalFlow += incrementalFlow;
        }
        return new MinCostFlowResult { TotalCost = totalCost, TotalFlow = totalFlow };
    }
}


public class PriorityQueue<T> {
    private T[] _array = new T[128];
    private int _size = 0;
    private readonly Comparison<T> _compare;

    public PriorityQueue() {
        _compare = Comparer<T>.Default.Compare;
    }

    public PriorityQueue(Comparison<T> comp) {
        _compare = comp;
    }

    public int Count { get { return _size; } }

    private void Swap(int a, int b) {
        var t = _array[a];
        _array[a] = _array[b];
        _array[b] = t;
    }

    private void Expand() {
        var newlist = new T[_array.Length << 1];
        Array.Copy(_array, newlist, _array.Length);
        _array = newlist;
    }

    public bool Any() {
        return _size > 0;
    }

    public void Enqueue(T newValue) {
        int pos = ++_size;
        if (_size >= _array.Length) {
            Expand();
        }
        _array[pos] = newValue;
        while (pos > 1) {
            int parent = pos >> 1;
            if (_compare(_array[parent], _array[pos]) > 0) {
                Swap(parent, pos);
                pos = parent;
            } else {
                break;
            }
        }
    }

    public T Peek() {
        return _array[1];
    }

    public T Dequeue() {
        var top = _array[1];
        int pos = 1;
        _array[pos] = _array[_size--];
        while ((pos << 1) <= _size) {
            int left = pos << 1;
            int right = left | 1;
            int next = left;
            if (right <= _size && _compare(_array[left], _array[right]) > 0) {
                next = right;
            }
            if (_compare(_array[pos], _array[next]) > 0) {
                Swap(next, pos);
                pos = next;
            } else {
                break;
            }
        }

        return top;
    }
};

