    for(auto e: edges){
        if(e.from == S || e.to == T || e.flow == 0) continue;
        masu[e.from][e.to-N] = 'X';
    }
    for(int i = 0; i < N;i++){
        for(int j = 0; j < N;j++){
            cout << masu[i][j];
        }cout << endl;
    }
    return res;
}
