	long long n, kk, i, j, k, id, INF = 1E9;
	cin >> n >> kk;
	vector<vector<long long>> a(n, vector<long long>(n));
	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++) {
			cin >> a[i][j];
			a[i][j] = INF - a[i][j];
		}
	}

	min_cost_flow fl(n * n + 2 * n + 2, 0, n * n + 2 * n + 1);

	for (i = 0; i < n; i++) {
		fl.add_path(0, i + 1, kk, 0, 0, 0);							// start --> row
		fl.add_path(n + i + 1, n * n + 2 * n + 1, kk, 0, 0, 0);		// column --> terminal
		fl.add_path(i + 1, n + i + 1, kk, 0, INF, -INF);
	}

	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++) {
			id = n * 2 + i * n + j + 1;
			fl.add_path(i + 1, id, 1, 0, a[i][j], -a[i][j]);
			fl.add_path(id, n + j + 1, 1, 0, 0, 0);
