struct edge { int to, cap, cost, rev, id; };

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec h, dist, prevv, preve;

    Graph(int N): N(N){
        G.resize(N);
        h.resize(N);
        dist.resize(N);
        prevv.resize(N);
        preve.resize(N);
    }

    void add_Directed_edge(int from, int to, int cap, int cost, int id = -1){
        G[from].push_back((edge){to, cap, cost, (int)G[to].size(), -1});
        G[to].push_back((edge){from, 0, -cost, (int)G[from].size() - 1, id});
    }

    //無理なら-1返す
    int min_cost_flow(int s, int t, int f){
        int res = 0;
        fill(all(h), 0);
        while(f > 0){
            priority_queue<Pii, vector<Pii>, greater<Pii>> que;
            fill(all(dist), INF);
            dist[s] = 0;
            que.push(Pii(0, s));
            while(!que.empty()){
                Pii p = que.top(); que.pop();
                int v = p.second;
                if(dist[v] < p.first) continue;
                REP(i, G[v].size()){
                    edge &e = G[v][i];
                    if(e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]){
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push(Pii(dist[e.to], e.to));
                    }
                }
            }
            if(dist[t] == INF) return -1;
            REP(v, N) h[v] += dist[v];

            int d = f;
            for(int v = t; v != s; v = prevv[v]){
                d = min(d, G[prevv[v]][preve[v]].cap);
            }
            f -= d;
            res += d * h[t];
            for(int v = t; v != s; v = prevv[v]){
                edge &e = G[prevv[v]][preve[v]];
                e.cap -= d;
                G[v][e.rev].cap += d;
            }
        }
        return res;
    }

    //実際の流量を求める
    vector<int> calc_flow(int num_id){
        vector<int> flow(num_id, 0);
        REP(v, N) for(auto e: G[v]) if(e.id >= 0 && e.id < num_id) flow[e.id] = e.cap;
        return flow;
    }
};


signed main(){

    int N, K; cin >> N >> K;
    mat A(N, vec(N)); cin >> A;

    const int maxA = 1000000000;
    Graph G(2 * N + 2);
    int s = 2 * N, t = s + 1;
    REP(i, N){
        G.add_Directed_edge(s, i, K, 0);
        G.add_Directed_edge(i + N, t, K, 0);
    }

    REP(i, N) REP(j, N){
        G.add_Directed_edge(i, j + N, 1, maxA - A[i][j], i * N + j);
    }

    int ans = 0, F = 0;
    vec v(N * N, 0);
    REP(i, N * N){
        int res = G.min_cost_flow(s, t, 1);
        if(res == -1) break;
        F += maxA - res;
        if(F > ans){
            ans = F;
            v = G.calc_flow(N * N);
        }
    }

    Out(ans);
    REP(i, N){
        REP(j, N){
            if(v[i * N + j]) cout << 'X';
            else cout << '.';
        }
        cout << endl;
    }

    return 0;
}

