    }
    flow.add_edge(N<<1,i,K,0);
    flow.add_edge(i+N,N<<1|1,K,pot[N+1]-pot[i]);
  }
  auto v=flow.slope(N<<1,N<<1|1);
  int M=v.size();
  rep1(i,M){
    if((v[i].first-v[i-1].first)*pot[N+1]<(v[i].second-v[i-1].second))break;
