bool SPFA()
{
	queue<int> q;
	for(int i=0;i<=t;i++) d[i]=inf;
	q.push(s),d[s]=0;
	while(!q.empty()){
		int u=q.front();
		q.pop(),inq[u]=false;
		for(int i=0;i<=t;i++){
			if(G[u][i]>0&&d[i]>d[u]+cost[u][i]){
				d[i]=d[u]+cost[u][i];
				pre[i]=u;
				if(!inq[i]){
					inq[i]=true;
					q.push(i);
				}
			}
		}
	}
	return d[t]<0;
}
