        ans.add_edge(n + i, t, k, 0ll);
    }
    ans.add_edge(s, t, n * k, INF);

    cout << INF * n * k - ans.flow(s, t, n * k).second << "\n";

    vector<string> res(n, string(n, '.'));
    for (auto p : ans.edges()) {
