typedef int FLOW;        // フローを表す型、今回は int 型
typedef int COST;        // コストを表す型、今回は int 型
const int MAX_V = 3000;      // グラフの最大ノード数
const COST INF = 100000000;   // 十分大きい値

// グラフの辺の構造体
struct Edge {
  int rev, from, to;
  FLOW cap, icap;
  COST cost;
  Edge(int r, int f, int t, FLOW ca, COST co) : rev(r), from(f), to(t), cap(ca), icap(ca), cost(co) {}
};

// グラフ構造体
struct Graph {
  int V;
  vector<Edge> list[MAX_V];

  Graph(int n = 0) : V(n) { for (int i = 0; i < MAX_V; ++i) list[i].clear(); }
  void init(int n = 0) { V = n; for (int i = 0; i < MAX_V; ++i) list[i].clear(); }
  void resize(int n = 0) { V = n; }
  void reset() { for (int i = 0; i < V; ++i) for (int j = 0; j < (int)list[i].size(); ++j) list[i][j].cap = list[i][j].icap; }
  inline vector<Edge>& operator [] (int i) { return list[i]; }

  Edge &redge(Edge &e) {
    if (e.from != e.to) return list[e.to][e.rev];
    else return list[e.to][e.rev + 1];
  }

  void addedge(int from, int to, FLOW cap, COST cost) {
    list[from].push_back(Edge((int)list[to].size(), from, to, cap, cost));
    list[to].push_back(Edge((int)list[from].size() - 1, to, from, 0, -cost));
  }
};

// 最小費用流を求める関数
COST MinCostFlow(Graph &G, int s, int t, FLOW inif) {
  COST dist[MAX_V];
  int prevv[MAX_V];
  int preve[MAX_V];

  COST res = 0;
  FLOW f = inif;
  while (f > 0) {
    fill(dist, dist + G.V, INF);
    dist[s] = 0;
    while (true) {
      bool update = false;
      for (int v = 0; v < G.V; ++v) {
        if (dist[v] == INF) continue;
        for (int i = 0; i < (int)G[v].size(); ++i) {
          Edge &e = G[v][i];
          if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
            dist[e.to] = dist[v] + e.cost;
            prevv[e.to] = v;
            preve[e.to] = i;
            update = true;
          }
        }
      }
      if (!update) break;
    }

    if (dist[t] == INF) return 0;

    FLOW d = f;
    for (int v = t; v != s; v = prevv[v]) {
      d = min(d, G[prevv[v]][preve[v]].cap);
    }
    f -= d;
    res += dist[t] * d;
    for (int v = t; v != s; v = prevv[v]) {
      Edge &e = G[prevv[v]][preve[v]];
      Edge &re = G.redge(e);
      e.cap -= d;
      re.cap += d;
    }
  }
  return res;
}


int main() {
  ll N, K;
  cin >> N >> K;

  // グラフの定義 (ノード数を引数に)
  Graph G(N * 2 + 2);       // +2 は S, T の分

  // スーパーノード S, T の index
  int from = N * 2;
  int to   = N * 2 + 1;

  // グラフに枝を張っていく
  for (int i = 0; i < N; ++i) {
    G.addedge( from,  i, K, 0);
    G.addedge(N + i, to, K, 0);
    G.addedge(    i, to, K, 0); //任意にとる線かな
    for (int j = 0; j < N; ++j) {
      int gain;
      cin >> gain;

      // 従業員 i から、仕事 j (index は j+NUM_WORKER) へと、容量 1, コスト -gain の枝を張る
      G.addedge(i, N + j, 1, -gain);
    }
  }

  // 最小費用流を求める なんでN*K??
  COST res = MinCostFlow(G, from, to, N*K);

  // 出力
  cout << -res << endl;

  vector<vector<char>> C(N, vector<char>(N, '.'));
  // 誰がどの仕事に割当てられたかを出力する
  for (int i = 0; i < N; ++i) {
    for (auto e : G[i]) {
      // 元々の容量 (e.icap) が 1 で、フローが流れて容量 (e.cap) が 0 になった部分が割り当てられたところ
      if (e.icap == 1 && e.cap == 0) {
        C[i][e.to - N] = 'X';
      }
    }
  }
  rep(i, N){
    rep(j, N){
      cout << C[i][j];
    }
    cout << endl;
  }

  return 0;
}

