    }
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < N; j++)
        {
            g.add_edge(i, N + j, 1, BIG - A[i][j]);
        }
    }
    auto result = g.flow(s, t, N * K);
    cout << 1LL * N * K * BIG - result.second << endl;



    vector<string> grid(N, string(N, '.'));

    auto edges = g.edges();

    for (auto e : edges)
    {
        if (e.from == s || e.to == t || e.flow == 0)
            continue;

        grid[e.from][e.to - N] = 'X';
    }

    for (int i = 0; i < N; i++)
    {
        cout << grid[i] << endl;
    }
}

