// Problem
void solve() {
    VAR(ll, n, k); //

    const ll BIG = 1'000'000'000;

    /**
     * generate (S -> row -> column -> T) graph
     * i行目 -> i
     * j列目 -> n + j
     **/
    mcf_graph<int, ll> g(2 * n + 2);
    int S = 2 * n, T = 2 * n + 1;

    // we can "waste" the flow
    g.add_edge(S, T, n * k, BIG);

    REP(i, 0, n) {
        g.add_edge(S, i, k, 0);     // i 行目に k だけ流せる
        g.add_edge(n + i, T, k, 0); // j 列目に k だけ流せる
    }

    REP(i, 0, n) REP(j, 0, n) {
        VAR(ll, a);
        g.add_edge(i, n + j, 1, BIG - a); // (i,j) に流すと a だけ得する
    }

    pair<int, ll> result = g.flow(S, T, n * k); // S->T で流す
    cout << (n * k * BIG - result.second) << endl;

    vc<string> grid(n, string(n, '.'));
    auto edges = g.edges();
    for (auto e : edges) {
        if (e.from == S || e.to == T || e.flow == 0) continue;

        grid[e.from][e.to - n] = 'X';
    }

    REP(i, 0, n) cout << grid[i] << endl;
}

// entry point
int main() {
    solve();
    return 0;
}

