void solve(int N, int K, vvi& a) {
    ll CEIL = 1e9;

    int V = 1 + N + N + 1;
    atcoder::mcf_graph<int, ll> g(V);
    rep(r, N) { g.add_edge(0, 1 + r, K, 0); }
    rep(r, N) rep(c, N) { g.add_edge(1 + r, 1 + N + c, 1, CEIL - a[r][c]); }
    rep(c, N) { g.add_edge(1 + N + c, V - 1, K, 0); }

    g.add_edge(0, V - 1, N * K, CEIL);

    pair<int, ll> fl = g.flow(0, V - 1, N * K);
    int flow = fl.first;
    ll cost = fl.second;
    ll real_cost = CEIL * flow - cost;

    vvi tmp(N, vi(N, '.'));
    for (auto& e : g.edges()) {
        if (IN(e.from, 1, N) && IN(e.to, 1 + N, N * 2)) {
            int r = e.from - 1, c = e.to - (1 + N);
            if (e.flow == 1) tmp[r][c] = 'X';
        }
    }

    cout << real_cost << endl;
    rep(r, N) {
        rep(c, N) { cout << (char)tmp[r][c]; }
        cout << endl;
    }

