const int64_t MX = 1e9;

void solve(int N, int K, vector<vector<int64_t>> A) {
    mcf_graph<int64_t, int64_t> graph(2 * N + 2);
    int s = 2 * N, t = 2 * N + 1;

    // s -> row
    for (int r = 0; r < N; r++) {
        graph.add_edge(s, r, K, 0);
    }
    // row -> col
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < N; c++) {
            graph.add_edge(r, N + c, 1, MX - A.at(r).at(c));
        }
    }
    // col -> t
    for (int c = 0; c < N; c++) {
        graph.add_edge(N + c, t, K, 0);
    }
    graph.add_edge(s, t, 2 * N, MX);

    auto res = graph.flow(s, t, 2 * N);
    vector<string> ans(N, string(N, '.'));
    for (auto&& e : graph.edges()) {
        if (e.from == s || e.to == t || e.flow == 0) continue;
        ans.at(e.from).at(e.to - N) = 'X';
    }

    cout << res.first * MX - res.second << endl;
    for (int r = 0; r < N; r++) {
        cout << ans.at(r) << endl;
    }
}

