using namespace std;
struct edge{
    int to;
    int cap;
    long long cost;
    int inv;
};
struct primal{
    long long INF;
    int V;
    vector<int> prevv, preve;
    vector<vector<edge>> G;
    primal(int N){
        V = N;
        prevv.resize(V);
        preve.resize(V);
        G.resize(V);
        INF = 1e18;
    }
    void add(int s, int t, int cap, long long cost){
        edge e1 = {t, cap, cost, (int)G[t].size()};
        G[s].push_back(e1);
        edge e2 = {s, 0, -cost, (int)G[s].size() - 1};
        G[t].push_back(e2);
    }
    long long solve(int s, int t, int f){
        long long res = 0;
        while(f > 0){
            vector<long long> d(V, INF);
            bool update = true;
            d[s] = 0;
            while(update){
                update = false;
                for(int i = 0; i < V; i++){
                    if(d[i] == INF) continue;
                    for(int j = 0; j < (int)G[i].size(); j++){
                        edge e = G[i][j];
                        if(e.cap > 0 && d[e.to] > d[i] + e.cost){
                            d[e.to] = d[i] + e.cost;
                            prevv[e.to] = i;
                            preve[e.to] = j;
                            update = true;
                        }
                    }
                }
            }
            if(d[t] == INF) return 1;
            int dmin = f;
            for(int v = t; v != s; v = prevv[v]){
                dmin = min(dmin, G[prevv[v]][preve[v]].cap);
            }
            f -= dmin;
            res += d[t] * dmin;
            for(int v = t; v != s; v = prevv[v]){
                edge &e = G[prevv[v]][preve[v]];
                e.cap -= dmin;
                G[v][e.inv].cap += dmin;
            }
        }
        return res;
    }
};

int main(){
    int N, K;
    cin >> N >> K;
    vector<vector<long long>> A(N, vector<long long>(N));
    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++) cin >> A[i][j];
    }
    primal pd(N * N + 2*N + 2);
    const int start = N * N + 2 * N, goal = N * N + 2 * N + 1;
    for(int i = 0; i < N; i++){
        pd.add(start, N * N + i, K, 0);
        pd.add(N * N + N + i, goal, K, 0);
    }
    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            pd.add(N * N + i, i * N + j, 1, 0);
            pd.add(i * N + j, N * N + N + j, 1, -A[i][j]);
        }
    }
    long long ans = 0;
    vector<vector<edge>> g;
    while(1){
        long long temp = pd.solve(start, goal, 1);
        if(temp > 0) break;
        ans += -temp;
        g = pd.G;
    }
    cout << ans << endl;
    vector<vector<char>> judge(N, vector<char>(N, '.'));
    for(int i = 0; i < N; i++){
        for(edge e: g[N * N + i]){
            if(e.to == start || e.cap > 0) continue;
            if(e.cap == 0){
                int x = e.to / N, y = e.to % N;
                judge[x][y] = 'X';
            }
        }
    }
    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++) cout << judge[i][j];
        cout << endl;
    }
}

