    pair<long long,long long> ans=mcf.flow(s,t,N*K);
    cout<<N*K*ABIG-ans.second<<endl;
    //cout<<ans.second<<","<<ABIG<<endl;

    vector<mcf_graph<long long,long long>::edge> eg=mcf.edges();

