int n, k;
vector<vector<lint>> a;

lint convert(lint cost) {
    lint big = 1e10;
    return big - cost;
}

int main() {
    cin >> n >> k;
    a.assign(n, vector<lint>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
        }
    }
    mcf_graph<lint, lint> g(2 * n + 2);
    int source = 2 * n;
    int sink = 2 * n + 1;
    g.add_edge(source, sink, n * k, convert(0));
    // row
    for (int i = 0; i < n; i++) {
        g.add_edge(source, i, k, 0);
    }
    // column
    for (int i = 0; i < n; i++) {
        g.add_edge(i + n, sink, k, 0);
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            g.add_edge(i, j + n, 1, convert(a[i][j]));
        }
    }
    g.flow(source, sink, n * k);
    vector<string> ans(n, string(n, '.'));
    lint score = 0;
    auto edges = g.edges();
    for (auto e : edges) {
        if (e.from == source || e.to == sink) {
