  }
  cout<<MOD*N*K-rock.flow(2*N,2*N+1,N*K).second<<endl;
  vector<vector<char>> ans(N,vector<char>(N,'.'));
  for(int i=0;i<N*(N+2)+1;i++){
    //cout<<rock.get_edge(i).from<<" "<<rock.get_edge(i).to<<" "<<rock.get_edge(i).flow<<" "<<endl;
    int v=rock.get_edge(i).from;
