int main(){

  ll N, K;
  cin >> N >> K;

  // 行 0 ~ N-1, 列 N ~ 2*N-1, S : 2*N, T : 2*N+1 の頂点を持つグラフを作成
  mcf_graph<ll, ll> graph(N * 2 + 2);
  ll S = 2*N;
  ll T = 2*N+1;


  // 考え方　※辺を（容量/コスト) で記載

  // S -> 行頂点 -> 列頂点 -> T へとフローを流す
  // S -> 行頂点 : (K/0)の辺を張る。「同じ行はK個しか選べない」を表現
  // 列頂点 -> T : (K/0)の辺を張る。同じく「同じ列はK個しか選べない」を表現
  // 行 i を表す頂点 -> 列 j を表す頂点 : (1/INF-A[i][j]) の辺を張る。(行iと行jの組み合わせ)とは「マスij」に他ならないので、その性質は「同じマスは1つしか選べない（容量が1）」「そのマスを選ぶと、A[i][j]点を得る（得点＝コストの反対なので、コストが-A[i][j]）」となる。ただし、コストを負にしてしまうと ACL の制約 0 <= cap, cost に引っかかるので、コストを INF-A[i][j] として扱う。
  // 求めたい合計得点は「選んだマスの数（行頂点から列頂点に流したフローの量）*INF - トータルコスト」となる。

  // しかし、これだと選んだマスの数を求めるのが少々面倒なので、以下のようにする
  // S -> T に (N*K/INF) の辺を張る。出力例2 のように、選ぶマスの数が N*K 以下になるような時は、この辺にフローが流れるようにすれば、合計得点を「N*K*INF - トータルコスト」で求められるようになる。


  // 辺を張る

  // 最初に 行頂点 -> 列頂点 に張ることで、最後の盤面構築の添字がやりやすくなる
  rep(i, N) rep(j, N){
    ll a = il();
    graph.add_edge(i, N+j, 1, INF-a);
  }
  rep(i, N) graph.add_edge(S, i, K, 0);
  rep(j, N) graph.add_edge(N+j, T, K, 0);
  graph.add_edge(S, T, N*K, INF);


  // フローを流す
  // 最大で N*K しか流れないようにしないと、S -> T に張った辺を自由に使って大量にフローを流してしまう
  // S -> T の辺は、あくまでそれ以外で N*K 未満しか選ばない方が効率的だった場合に残りを補うためなので、必要より多く（N*Kより多く）流れないようにする
  pair<ll, ll> ansp = graph.flow(S, T, N*K);
  cout << N*K*INF - ansp.second << endk;


  // 答えの構築
  // 返り値 res[k] := k 番目に追加した辺（＝マス）、の状態 であり、edge.flow に「結果として流れたフロー」が入っている。
  // 「結果として流れたフロー」が 1 であれば、その辺を選んだ = そのマスを選んだ ということ
  vector<string> cells(N, string(N, '.'));

  vector<mcf_graph<ll, ll>::edge> graph_condition = graph.edges();
  rep(i, N) rep(j, N){
    if (graph_condition[i*N + j].flow == 1) cells[i][j] = 'X';
  }

  rep(i, N) cout << cells[i] << endk;



}

