  int N,K;
  cin >> N >> K;

  vector<vector<int>> a(N,vector<int>(N));
  REP(i,N) REP(j,N) cin >> a[i][j];

  min_cost_flow<int,int> mcf(N*2+2);
  int s = N*2, t = s+1;
  mcf.add_edge(s,t,N*K,INF);
  REP(i,N) mcf.add_edge(s,i,K,0), mcf.add_edge(i+N,t,K,0); 
  REP(i,N) REP(j,N){
    mcf.add_edge(i,j+N,1,INF-a[i][j]);
  }

  auto res = mcf.flow(s,t,N*K);
