    int N,K;cin>>N>>K;
    vector<vector<ll>> A(N,vector<ll>(N));
    for(int i=0;i<N;i++) for(int j=0;j<N;j++) cin>>A[i][j];

    atcoder::mcf_graph<ll,ll> graph(2*N+2);

    graph.add_edge(2*N,2*N+1,N*K,INF);

    for(int i=0;i<N;i++){
