    vector<string> ans(N, string(N, '.'));
    for (auto e:graph.edges()) {
        if (e.flow == 0 || e.from == s || e.to == t) { continue; }
        ans[e.from][e.to - N] = 'X';
    }
    rep(i, N) { cout << ans[i] << endl; }
}

