inline int solve(){
    atcoder::mcf_graph<ll, ll> g(2*N+10);
    int s = 0, t = 2*N+1;
    ll INF = 1e9;
    for (int i = 1; i <= N; i++)
    {
        g.add_edge(s, i, K, 0);
        g.add_edge(N+i, t, K, 0);
    }
    g.add_edge(s, t, N*K, INF);
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < N; j++)
        {
            g.add_edge(i+1, N+j+1, 1, INF - A[i][j]);
        }
    }
    ll _cap, cost;
    tie(_cap, cost) = g.flow(s, t, N*K);
