#define inf 0x3f3f3f3f
const int maxn=105;
int n,m,s,t,G[105][105],cost[105][105];
int d[maxn],inq[maxn],pre[maxn];
void read(int& ret)
{
	ret=0;
	char ch=getchar();
	while(ch<'0'||ch>'9') ch=getchar();
	while(ch>='0'&&ch<='9') ret=(ret<<3)+(ret<<1)+ch-'0',ch=getchar();
}
void build()
{
	for(int i=1;i<=n;i++) G[s][i]=m;
	for(int i=n+1;i<t;i++) G[i][t]=m;
	for(int i=1,x;i<=n;i++){
		for(int j=n+1;j<t;j++){
			read(x);
			G[i][j]=1,cost[i][j]=-x,cost[j][i]=x;
		}
	}
}
bool SPFA()
{
	queue<int> q;
	memset(d,inf,sizeof(d));
	q.push(s);
	d[s]=0;
	while(!q.empty()){
		int u=q.front();
		q.pop(),inq[u]=false;
		for(int i=0;i<=t;i++){
			if(G[u][i]>0&&d[i]>d[u]+cost[u][i]){
				d[i]=d[u]+cost[u][i];
				pre[i]=u;
				if(!inq[i]){
					inq[i]=true;
					q.push(i);
				}
			}
		}
	}
	return d[t]<0;
}
int main()
{
	read(n),read(m);
	s=0,t=2*n+1;
	build();
	int ans=0;
	while(SPFA()){
		ans-=d[t];
		for(int i=t;i!=s;i=pre[i]){
			G[pre[i]][i]--;
			G[i][pre[i]]++;
		}
	}
	printf("%d\n",ans);
	for(int i=1;i<=n;i++){
		for(int j=n+1;j<t;j++){
			if(G[i][j]!=1) printf("X");
			else printf(".");
		}
		puts("");
	}
	return 0;
}

