using namespace std;
using namespace atcoder;

void solve(int N, int K, vector<vector<int>> A) {
    mcf_graph<int64_t, int64_t> graph(2 * N + 2);
    int s = 2 * N, t = 2 * N + 1;

    // s -> row
    for (int r = 0; r < N; r++) {
        graph.add_edge(s, r, K, 0);
    }
    // row -> col
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < N; c++) {
            graph.add_edge(r, N + c, 1, INT_MAX - A.at(r).at(c));
        }
    }
    // col -> t
    for (int c = 0; c < N; c++) {
        graph.add_edge(N + c, t, K, 0);
    }
    graph.add_edge(s, t, N * N, INT_MAX);

    auto res = graph.flow(s, t, N * N);
    vector<string> ans(N, string(N, '.'));
    for (auto&& e : graph.edges()) {
        if (e.from == s || e.to == t || e.flow == 0) continue;
        ans.at(e.from).at(e.to - N) = 'X';
    }

    cout << res.first * INT_MAX - res.second << endl;
    for (int r = 0; r < N; r++) {
        cout << ans.at(r) << endl;
    }
}

int main() {
    int N;
    cin >> N;
    int K;
    cin >> K;
    vector<vector<int>> A(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> A.at(i).at(j);
        }
    }
    solve(N, K, move(A));
    return 0;
}

