// AtCoder Library(https://img.atcoder.jp/practice2/ac-library.zip)
// -> 一部改変(2020/09/13).
template <class Cap, class Cost> struct mcf_graph {
public:
    mcf_graph(){}
    mcf_graph(int n) : _n(n), g(n){}
    int add_edge(int from, int to, Cap cap, Cost cost){
        assert(0 <= from && from < _n);
        assert(0 <= to && to < _n);
        int m = int(pos.size());
        pos.pb({from, int(g[from].size())});
        g[from].pb(_edge{to, int(g[to].size()), cap, cost});
        g[to].pb(_edge{from, int(g[from].size()) - 1, 0, -cost});
        return m;
    }
    struct edge {
        int from, to;
        Cap cap, flow;
        Cost cost;
    };
    edge get_edge(int i){
        int m = int(pos.size());
        assert(0 <= i && i < m);
        auto _e = g[pos[i].a][pos[i].b];
        auto _re = g[_e.to][_e.rev];
        return edge{
            pos[i].a, _e.to, _e.cap + _re.cap, _re.cap, _e.cost,
        };
    }
    vector<edge> edges(){
        int m = int(pos.size());
        vector<edge> result(m);
        rep(i, m) result[i] = get_edge(i);
        return result;
    }
    pair<Cap, Cost> flow(int s, int t){
        return flow(s, t, numeric_limits<Cap>::max());
    }
    pair<Cap, Cost> flow(int s, int t, Cap flow_limit){
        return slope(s, t, flow_limit).back();
    }
    vector<pair<Cap, Cost>> slope(int s, int t){
        return slope(s, t, numeric_limits<Cap>::max());
    }
    vector<pair<Cap, Cost>> slope(int s, int t, Cap flow_limit){
        assert(0 <= s && s < _n);
        assert(0 <= t && t < _n);
        assert(s != t);
        vector<Cost> dual(_n, 0), dist(_n);
        vector<int> pv(_n), pe(_n);
        vector<bool> vis(_n);
        auto dual_ref = [&](){
            fill(all(dist), numeric_limits<Cost>::max());
            fill(all(pv), -1);
            fill(all(pe), -1);
            fill(all(vis), false);
            struct Q{
                Cost key;
                int to;
                bool operator<(Q r) const{ return key > r.key; }
            };
            priority_queue<Q> pq;
            dist[s] = 0;
            pq.push(Q{0, s});
            while(!pq.empty()){
                int v = pq.top().to;
                pq.pop();
                if(vis[v]) continue;
                vis[v] = true;
                if(v == t) break;
                rep(i, int(g[v].size())){
                    auto e = g[v][i];
                    if(vis[e.to] || !e.cap) continue;
                    Cost cost = e.cost - dual[e.to] + dual[v];
                    if(dist[e.to] - dist[v] > cost){
                        dist[e.to] = dist[v] + cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push(Q{dist[e.to], e.to});
                    }
                }
            }
            if(!vis[t]) return false;
            rep(v, _n){
                if(!vis[v]) continue;
                dual[v] -= dist[t] - dist[v];
            }
            return true;
        };
        Cap flow = 0;
        Cost cost = 0, prev_cost = -1;
        vector<pair<Cap, Cost>> result;
        result.pb({flow, cost});
        while(flow < flow_limit){
            if(!dual_ref()) break;
            Cap c = flow_limit - flow;
            for(int v = t; v != s; v = pv[v]){
                c = min(c, g[pv[v]][pe[v]].cap);
            }
            for(int v = t; v != s; v = pv[v]){
                auto& e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
            }
            Cost d = -dual[s];
            flow += c;
            cost += c * d;
            if(prev_cost == d) result.pop_back();
            result.pb({flow, cost});
            prev_cost = cost;
        }
        return result;
    }
private:
    int _n;
    struct _edge{
        int to, rev;
        Cap cap;
        Cost cost;
    };
    vector<pair<int, int>> pos;
    vector<vector<_edge>> g;
};

// mincostflow.html を 参照.
int main(){

    int n, k;
    scanf("%d %d", &n, &k);
    /**
     * generate (s -> row -> column -> t) graph
     * i-th row correspond to vertex i
     * i-th col correspond to vertex n + i
     **/
    mcf_graph<int, LL> g(2 * n + 2);
    int s = 2 * n, t = 2 * n + 1;
    // we can "waste" the flow
    g.add_edge(s, t, n * k, BIG);
    rep(i, n){
        g.add_edge(s, i, k, 0);
        g.add_edge(n + i, t, k, 0);
    }
    rep(i, n){
        rep(j, n){
            LL a;
            scanf("%lld", &a);
            g.add_edge(i, n + j, 1, BIG - a);
        }
    }
    auto result = g.flow(s, t, n * k);
    printf("%lld\n", 1LL * n * k * BIG - result.b);

    vector<string> grid(n, string(n, '.'));
    auto edges = g.edges();
    for(auto e : edges){
        if(e.from == s || e.to == t || e.flow == 0) continue;
        grid[e.from][e.to - n] = 'X';
    }
