template <class T, class S> T make_vec(S x) { return x; }
template <class T, class... Ts> auto make_vec(size_t n, Ts... ts) {
    return std::vector<decltype(make_vec<T>(ts...))>(n, make_vec<T>(ts...));
}

constexpr Int C = 1e9;
signed main() {
    Int n, K;
    std::cin >> n >> K;
    auto A = make_vec<Int>(n, n, 0);
    REP(i, n) REP(j, n) std::cin >> A[i][j];
    atcoder::mcf_graph<Int, Int> g(n * n + 2 * n + 2);
    Int s = n * n + 2 * n, t = n * n + 2 * n + 1;
    auto enc = [&](Int i, Int j) { return i * n + j; };
    REP(i, n) g.add_edge(s, n * n + i, K, 0);
    REP(j, n) g.add_edge(n * n + n + j, t, K, 0);
    REP(i, n) {
        REP(j, n) {
            g.add_edge(n * n + i, enc(i, j), 1, C - A[i][j]);
            g.add_edge(enc(i, j), n * n + n + j, 1, 0);
        }
    }
    g.add_edge(s, t, n * K, C);
    auto res = g.flow(s, t, n * K);
    std::cout << C * res.first - res.second << std::endl;
    std::vector<std::string> ans(n, std::string(n, '.'));
    for (const auto& e : g.edges()) {
        if (e.to >= n * n || e.flow == 0) continue;
        Int i = e.to / n, j = e.to % n;
        ans[i][j] = 'X';
    }
    for (auto& s : ans) std::cout << s << "\n";
}

