ll solve() {
    ll N, K, a;
    cin >> N >> K;
    atcoder::mcf_graph<ll, ll> g(2*N+2);
    int vs = 2*N, vt = 2*N+1;
    ll MA = 1e9;
    for ( int i = 0; i < N; i++ ) {
        for ( int j = 0; j < N; j++ ) {
            cin >> a;
            g.add_edge(i, N+j, 1, MA-a);
        }
    }
    for ( int i = 0; i < N; i++ ) {
        g.add_edge(vs, i, K, 0);
        g.add_edge(N+i, vt, K, 0);
    }
    // 選ばない
    g.add_edge(vs, vt, N*K, MA);

    auto f = g.flow(vs, vt, N*K);

    vector<string> ans(N, string(N, '.'));
    for ( auto e : g.edges() ) {
        if ( e.from != vs && e.to != vt && e.flow > 0 ) {
            ans[e.from][e.to-N] = 'X';
        }
    }
    cout << (MA*K*N)-f.second << "\n";
    for ( auto ans1 : ans ) {
        cout << ans1 << "\n";
    }

    return 0;
}

