void add_edge(int from, int to, int cap, int cost) {
	edge fe = { to,cap,cost,(int)G[to].size() };
	edge toe = { from,0,-cost,(int)G[from].size() };
	G[from].pb(fe);
	G[to].pb(toe);
}

ll min_cost_flow(int s, int t, int f) {
	ll res = 0;
	int flag = 0;
	while (f > 0) {
		for (int i = 0; i < V; i++)dist[i] = inf;
		dist[s] = 0;

		if (flag == 0) {
			for (int i = 0; i < V - 1; i++) {
				for (int j = 0; j < V; j++) {
					for (int k = 0; k < G[j].size(); k++) {
						edge &e = G[j][k];
						if (dist[j] == inf)continue;
						if (e.cap > 0 && dist[e.to] > dist[j] + e.cost) {
							dist[e.to] = dist[j] + e.cost;
							prevv[e.to] = j;
							preve[e.to] = k;
						}
					}
				}
			}
			flag = 1;
		}
		else {
			min_priority_queue<pair<ll, ll>>que;
			que.push({ 0,s });
			while (que.size()) {
				auto p = que.top();
				que.pop();
				int v = p.second;
				if (dist[v] < p.first)continue;
				for (int i = 0; i < G[v].size(); i++) {
