			mf=p.first;
		}
	}

	build();
	g.flow(0, 1, mf);
	for(auto e : g.edges()) if(hb<=e.from && e.from<hb+n){
		int i=(e.to-ab)/n, j=(e.to-ab)%n;
		if(e.flow) s[i][j]='X';
		else s[i][j]='.';
	}

	cout<<mx<<endl;
	rep(i, n) cout<<s[i]<<endl;
	return 0;
}

