const int64_t INF = 1e18;
struct MinCostFlow{
    struct edge {
        int64_t to, cap, cost, rev;
        edge(int64_t to, int64_t cap, int64_t cost, int64_t rev):to(to), cap(cap), cost(cost), rev(rev){}
    };

    int N, S, T;
    int64_t flow;
    int64_t cost;
    vector<vector<edge>> G;
    vector<pair<int, int>> prv; // {v, e};
    vector<int64_t> h;

    MinCostFlow(int N, int S, int T):N(N), S(S), T(T){
        flow = cost = 0;
        G.resize(N);
        prv.resize(N);
        h.resize(N);
    }

    void add_edge(int64_t from, int64_t to, int64_t cap, int64_t cost){
        G[from].emplace_back(to, cap, cost, G[to].size());
        G[to].emplace_back(from, 0, -cost, G[from].size()-1);
    }

    int64_t calculate(int64_t f){
        typedef pair<int64_t, int> P;

        int64_t res = 0;
        vector<int64_t> dist(N);

        while(f > flow){
            priority_queue<P, vector<P>, greater<P>> que;
            fill(dist.begin(), dist.end(), INF);
            dist[S] = 0;
            que.push({0, S});
            while(que.size()){
                auto p = que.top(); que.pop();
                int64_t d = p.first;
                int i = p.second;
                if(d > dist[i]) continue;
                for(int idx=0; idx<int(G[i].size()); idx++){
                    auto& e = G[i][idx];
                    int j = e.to;
                    int64_t d2 = d + e.cost + h[i] - h[j];
                    if(e.cap > 0 && dist[j] > d2){
                        dist[j] = d2;
                        prv[j] = {i, idx};
                        que.push({dist[j], j});
                    }
                }
            }
            if(dist[T] == INF) return -1;
            for(int i=0; i<N; i++) h[i] += dist[i];

            int64_t d = f - flow;
            for(int i=T; i!=S; i=prv[i].first){
                auto& e = G[prv[i].first][prv[i].second];
                d = min(d, e.cap);
            }
            flow += d;
            res += d * h[T];
            for(int i=T; i!=S; i=prv[i].first){
                auto& e = G[prv[i].first][prv[i].second];
                e.cap -= d;
                G[i][e.rev].cap += d;
            }
        } 
        return res;
    }
};

int main(){
    int N, K;
    cin >> N >> K;
