    for(int i=0; i<N; i++) for(int j=0; j<N; j++) solver.add_edge(i, N+j, 1, OFFSET-A[i][j]);
    int64_t ans = OFFSET*K*N - solver.calculate(K*N);

    vector<string> X(N, string(N, '.'));
    for(int i=0; i<N; i++) for(auto& e : solver.G[i]) if(e.cap == 0) X[i][e.to-N] = 'X';
    cout << ans << endl;
    for(auto& s : X) cout << s << endl;
