  }
  cout << -pd.minimum_cost_flow(S, T) << '\n';
  REP(i, n) {
    vector<bool> ans(n);
    for (auto e : pd.graph[i]) {
      if (n <= e.dst && e.dst < n * 2) ans[e.dst - n] = e.cap == 0;
    }
    REP(j, n) cout << (ans[j] ? 'X' : '.');
    cout << '\n';
  }
  return 0;
}

