    const ll S=n*(n+2),T=S+1;
    rep(n) f.add_edge(S, n*n+i, k, 0);
    rep(n) f.add_edge(n*n+n+i, T, k, 0);
    rep(n) rep(j, n){
        f.add_edge(n*n+i, i*n+j, 1, -a[i][j]);
        f.add_edge(i*n+j, n*n+n+j, 1, 0);
    }
    out(-f.min_cost_flow(S, T));
    vec(string,ans,n,string(n,'.'));
