template<typename T> bool chmax(T &x, const T &y) {return (x < y)? (x = y, true) : false;};
template<typename T> bool chmin(T &x, const T &y) {return (x > y)? (x = y, true) : false;};

template<typename T>
struct Min_Cost_Flow{
    struct edge{
        int to; T cap, cost; int rev;
        edge(int to, T cap, T cost, int rev) : to(to), cap(cap), cost(cost), rev(rev) {} 
    };

    vector<vector<edge>> es;
    vector<T> d;
    vector<int> pre_v, pre_e;
    const T INF_T;
    const int n;

    Min_Cost_Flow(int n) : INF_T(numeric_limits<T>::max()), n(n){
        es.resize(n), d.resize(n), pre_v.resize(n), pre_e.resize(n);
    }

    void add_edge(int from, int to, T cap, T cost){
        es[from].eb(to, cap, cost, sz(es[to]));
        es[to].eb(from, 0, -cost, sz(es[from])-1);
    }

    void bellman_ford(int s){
        fill(all(d), INF_T);
        d[s] = 0;
        while(true){
            bool update = false;
            rep(i, n){
                if(d[i] == INF_T) continue;
                rep(j, sz(es[i])){
                    edge &e = es[i][j];
                    if(e.cap > 0 && chmin(d[e.to], d[i]+e.cost)){
                        pre_v[e.to] = i, pre_e[e.to] = j;
                        update = true;
                    }
                }
            }
            if(!update) break;
        }
    }

    T min_cost_flow(int s, int t, T flow){
        T ret = 0;
        while(flow > 0){
            bellman_ford(s);
            if(d[t] == INF_T) return -1;
            T f = flow;
            for(int now = t; now != s; now = pre_v[now]){
                chmin(f, es[pre_v[now]][pre_e[now]].cap);
            }
            ret += f*d[t], flow -= f;
            for(int now = t; now != s; now = pre_v[now]){
                edge &e = es[pre_v[now]][pre_e[now]];
                e.cap -= f, es[now][e.rev].cap += f;
            }
        }
        return ret;
    }
};

int main(){
    int N, K;
    cin >> N >> K;
    Min_Cost_Flow<ll> G(2*N+2);
    int s = 2*N, t = 2*N+1;
    rep(i, N){
        G.add_edge(s, i, K, 0), G.add_edge(N+i, t, K, 0);
        rep(j, N){
            ll A; cin >> A;
            G.add_edge(i, N+j, 1, -A);
        }
    }
    G.add_edge(s, t, K*N, 0);
    cout << -G.min_cost_flow(s, t, K*N) << endl;
    char ans[N][N];
    rep(i, N){
        for(auto &e: G.es[i]){
            if(e.to == s) continue;
            ans[i][e.to-N] = (e.cap == 0? 'X' : '.');
        }
    }
    rep(i, N){
        rep(j, N) cout << ans[i][j];
        cout << endl;
    }
}

