void add_edge(int from, int to, int cap, int cost) {
	edge fe = { to,cap,cost,(int)G[to].size() };
	edge toe = { from,0,-cost,(int)G[from].size() };
	G[from].pb(fe);
	G[to].pb(toe);
}

ll min_cost_flow(int s, int t, int f) {
	ll res = 0;
	int flag = 0;
	while (f > 0) {
		for (int i = 0; i < V; i++)dist[i] = inf;
		dist[s] = 0;

		if (flag == 0) {
			for (int i = 0; i < V - 1; i++) {
				for (int j = 0; j < V; j++) {
					for (int k = 0; k < G[j].size(); k++) {
						edge &e = G[j][k];
						if (dist[j] == inf)continue;
						if (e.cap > 0 && dist[e.to] > dist[j] + e.cost) {
							dist[e.to] = dist[j] + e.cost;
							prevv[e.to] = j;
							preve[e.to] = k;
						}
					}
				}
			}
			flag = 1;
		}
		else {
			min_priority_queue<pair<ll, ll>>que;
			que.push({ 0,s });
			while (que.size()) {
				auto p = que.top();
				que.pop();
				int v = p.second;
				if (dist[v] < p.first)continue;
				for (int i = 0; i < G[v].size(); i++) {
					edge &e = G[v][i];
					if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
						dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
						prevv[e.to] = v;
						preve[e.to] = i;
						que.push({dist[e.to],e.to});
					}
				}
			}
		}

		if (dist[t] == inf)return -1;
		for (int i = 0; i < V; i++)h[i] += dist[i];


		//s-t最短路に沿って目いっぱい流す
		ll d = f;
		for (int v = t; v != s; v = prevv[v]) {
			d = min(d, G[prevv[v]][preve[v]].cap);
		}
		f -= d;
		res += d * h[t];
		for (int v = t; v != s; v = prevv[v]) {
			edge &e = G[prevv[v]][preve[v]];
			e.cap -= d;
			G[v][e.rev].cap += d;
		}

      if (ans > res) {
			ans = res;
			memset(rec,0,sizeof(rec));
			for (int i = 1; i <= N; i++) {
				for (int j = 0; j < G[i].size(); j++) {
					edge e = G[i][j];
					if (e.cap == 0)rec[i][e.to] = 1;
				}
			}
		}
	}
	return res;
}


int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);


	cin >> N >> K;
	V = 2 * N + 2;
	for (int i = 1; i <= N; i++)add_edge(0,i,K,0);
	for (int i = N + 1; i <= 2 * N; i++)add_edge(i,2*N+1,K,0);
	for (int i = 1; i <= N; i++) {
		for (int j = N+1; j <= 2*N; j++) {
			int A;
			cin >> A;
			add_edge(i,j,1,-A);
		}
	}
	min_cost_flow(0, 2 * N + 1, 60 * 60);


	puts(-ans);
	for (int i = 1; i <= N; i++) {
		for (int j = N+1; j <= 2*N; j++) {
			if(rec[i][j])cout << "X";
			else cout << ".";
		}
		puts("");
	}


	return 0;
}

