        long[][] a = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = sc.nextLong();
            }
        }
        MinCostFlow mcf = new MinCostFlow(n * n + 2 * n + 2);
        int s = n * n + 2 * n;
        int t = s + 1;
        int r = n * n;
        int c = n * n + n;
        for (int i = 0; i < n; i++) {
            mcf.addEdge(s, r + i, k, 0);
            mcf.addEdge(c + i, t, k, 0);
        }
        long INF = 1l << 50;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mcf.addEdge(r + i, i * n + j, 1, INF - a[i][j]);
                mcf.addEdge(i * n + j, c + j, 1, 0);
            }
        }
        long maxf = 0;
        long max = 0;
        var slope = mcf.minCostSlope(s, t);
        for (var e : slope) {
            long flow = e[0];
            long cost = e[1];
            long x = flow * INF - cost;
            if (x > max) {
                max = x;
                maxf = flow;
            }
        }
        mcf.reset();
        mcf.minCost(s, t, maxf);
        pw.println(max);
