import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();
		int[][] a = new int[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				a[i][j] = sc.nextInt();
			}
		}
		sc.close();

		long BIG = 1000000000;
		MinCostFlow mcf = new MinCostFlow(n * 2 + 2);
		int s = n * 2;
		int t = s + 1;
		mcf.addEdge(s, t, n * k, BIG);

		for (int i = 0; i < n; i++) {
			mcf.addEdge(s, i, k, 0);
			mcf.addEdge(n + i, t, k, 0);
		}

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				mcf.addEdge(i, n + j, 1, BIG - a[i][j]);
			}
		}

		long[] result = mcf.flow(s, t, n * k);
		System.out.println(BIG * n * k - result[1]);

		char[][] c = new char[n][n];
		for (int i = 0; i < n; i++) {
			Arrays.fill(c[i], '.');
		}
		List<MinCostFlow.Edge> edges = mcf.edges();
		for (MinCostFlow.Edge e : edges) {
			if (e.from != s && e.to != t && e.flow > 0) {
				c[e.from][e.to - n] = 'X';
			}
		}

		for (int i = 0; i < n; i++) {
			System.out.println(c[i]);
		}
	}
}

