		// graph
		class Graph {
			int numNode;
			int numEdge;
			boolean directed;
			Set<Edge> edges = new HashSet<>();
			Node nodes[];
			Node reversedNodes[];

			Graph(int numNode, int numEdge, boolean directed) {
				this.numNode = numNode;
				this.numEdge = numEdge;
				this.directed = directed;
				nodes = new Node[numNode];
				reversedNodes = new Node[numNode];
				for(int i = 0; i < numNode; i ++) {
					nodes[i] = new Node(i);
					reversedNodes[i] = new Node(i);
				}
			}

			void init(Set<Edge> edges) {
				this.edges = edges;
				for(Edge e : edges) add(e);
			}

			void add(Edge e) {
				edges.add(e);
				nodes[e.source].add(e.target, e.cost);
				if(directed) reversedNodes[e.target].add(e.source, e.cost);
				else nodes[e.target].add(e.source, e.cost);
			}

			void remove(Edge e) {
				edges.remove(e);
				nodes[e.source].remove(e.target, e.cost);
				if(directed) reversedNodes[e.target].remove(e.source, e.cost);
				else nodes[e.target].remove(e.source, e.cost);
			}

			void update(Edge e, long cost) {
				nodes[e.source].update(e.target, cost);
				if(directed) reversedNodes[e.target].update(e.source, cost);
				else nodes[e.target].update(e.source, cost);
				e.cost = cost;
			}
			void update(int source, int target, long cost) { update(new Edge(source, target, cost), cost); }

			void clearNodes() {
				for(Node n : nodes) n.clear();
				for(Node n : reversedNodes) n.clear();
			}
		}

		class Node extends HashSet<Edge> {
			int id;

			Node(int id) { this.id = id; }
			void add(int target, long cost) { add(new Edge(id, target, cost)); }
			void remove(int target, long cost) { remove(new Edge(id, target, cost)); }
			void update(int target, long cost) { remove(target, cost); add(target, cost); }
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}


			@Override
			public String toString() { return source+" - "+cost+" -> "+target; }
			@Override
			public int hashCode() { return Objects.hash(source, target); }
			@Override
			public boolean equals(Object obj) {
				if(this == obj) return true;
				if(obj == null) return false;
				if(this.getClass() != obj.getClass()) return false;
				Edge that = (Edge) obj;
				if(this.source != that.source) return false;
				if(this.target != that.target) return false;
				return true;
			}
			@Override
			public int compareTo(Edge that) {
				int c = Long.compare(this.cost, that.cost);
				if(c == 0) c = Integer.compare(this.source, that.source);
				if(c == 0) c = Integer.compare(this.target, that.target);
				return c;
			}
		}

		class PairLL implements Comparable<PairLL> {
			long a; long b;
			PairLL() { }
			PairLL(long a, long b) { this.a = a; this.b = b; }
			@Override public String toString() { return "("+a+", "+b+")"; }
			@Override public int hashCode() { return Objects.hash(a, b); }
			@Override
			public boolean equals(Object obj) {
				if(this == obj) return true;
				if(obj == null) return false;
				if(this.getClass() != obj.getClass()) return false;
				PairLL that = (PairLL) obj;
				if(this.a != that.a || this.b != that.b) return false;
				return true;
			}
			@Override
			public int compareTo(PairLL that) {
				int c = Long.compare(this.a, that.a);
				if(c == 0) c = Long.compare(this.b, that.b);
				return c;
			}
		}

public void solve() {
	int num = ni();
	int kk = ni();
	long a[][] = nl(num, num);

	int numNode = num * 2 + 1;
	long d[] = new long[numNode];
	for(int i = 0; i < num; i ++) {
		d[i] = kk;
		d[num + i] = - kk;
	}
	NormalizedMinCostFlow nmcf = new NormalizedMinCostFlow(numNode, d);
	for(int i = 0; i < num; i ++) {
		for(int j = 0; j < num; j ++) {
			nmcf.addEdge(i, num + j, 1, - a[i][j]);
		}
	}
	for(int i = 0; i < num; i ++) {
		nmcf.addEdge(i, numNode - 1, INF, 0);
		nmcf.addEdge(numNode - 1, num + i, INF, 0);
	}
	PairLL ans = nmcf.minCostFlow();
	prtln(- ans.b);
	char c[][] = new char[num][num];
	fill(c, '.');
	for(MinCostFlow.WeightedCapEdge e : nmcf.edgesList) {
		if(e.source >= num * 2 || e.target >= num * 2 || e.source < e.target) continue;
		if(e.getFlow() == 0) c[e.target][e.source - num] = 'X';
	}
	prtln(c);
}

// WeightedCapEdge(source, target, cap, cost)
// PairLL(flow, cost)
class NormalizedMinCostFlow extends MinCostFlow { // V=numNode, E=numEdge, F=in
	long in;
	long sum;
	int s;
	int t;
	long d[];
	int idx[];
	int tsIdx;
	NormalizedMinCostFlow(int numNode, long[] d) { // O(V)
		super(numNode + 2);
		this.d = d;
		in = 0;
		sum = 0;
		s = numNode;
		t = numNode + 1;
		idx = new int[numNode];

		for(int i = 0; i < numNode; i++) {
			if(d[i] >= 0) {
				idx[i] = super.addEdge(s, i, d[i], 0);
				super.addEdge(i, t, 0, 0);
				in += d[i];
			}else {
				super.addEdge(s, i, 0, 0);
				idx[i] = super.addEdge(i, t, - d[i], 0);
			}
		}
	}

	void addDemand(int i, long addD) { if(i >= d.length) return; changeDemand(i, d[i] + addD); } // O(1)
	void changeDemand(int i, long newD) { // O(1)
		if(i >= d.length) return;
		if(d[i] > 0) in -= d[i];
		edgesList.get(idx[i]).cap = 0;
		d[i] = newD;
		if(d[i] >= 0) idx[i] &= ~1; else idx[i] |= 1;
		if(d[i] > 0) in += d[i];
		edgesList.get(idx[i]).cap = abs(d[i]);
	}

	int addEdge(int source, int target, long cap, long cost) { return addEdge(source, target, 0, cap, cost); } // O(1)
	int addEdge(int source, int target, long minCap, long maxCap, long cost) { // O(1)
		if(cost < 0) {
			sum += cost * maxCap;
			addDemand(source, - maxCap);
			addDemand(target, maxCap);
			return super.addEdge(target, source, maxCap - minCap, - cost);
		}else {
			sum += cost * minCap;
			addDemand(source, - minCap);
			addDemand(target, minCap);
			return super.addEdge(source, target, maxCap - minCap, cost);
		}
	}

	// O(F(V+E)logV)
	PairLL minCostFlow() {
		PairLL ans = minCostFlow(s, t, in);
		ans.b += sum;
		return ans;
	}
}


// WeightedCapEdge(source, target, cap, cost)
// PairLL(flow, cost)
class MinCostFlow { // V=numNode, E=numEdge
	class WeightedCapEdge {
		int source;
		int target;
		long cap;
		long cost;
		int rev;
		WeightedCapEdge(int source, int target, long cap, long cost, int rev) {
			this.source = source;
			this.target = target;
			this.cap = cap;
			this.cost = cost;
			this.rev = rev;
		}

		long getFlow() { return edges[target][rev].cap; }

		@Override
		public String toString() { return source+" - ("+cap+", "+cost+") -> "+target; }
		@Override
		public int hashCode() { return Objects.hash(source, target); }
		@Override
		public boolean equals(Object obj) {
			if(this == obj) return true;
			if(obj == null) return false;
			if(this.getClass() != obj.getClass()) return false;
			Edge that = (Edge) obj;
			if(this.source != that.source) return false;
			if(this.target != that.target) return false;
			return true;
		}
	}

	int numNode;
	int numEdge;
	List<WeightedCapEdge> edgesList;
	int len[];
	WeightedCapEdge edges[][];
	long potential[];

	MinCostFlow(int numNode) { // O(V)
		this.numNode = numNode;
		edgesList = new ArrayList<>();
		len = new int[numNode];
		edges = new WeightedCapEdge[numNode][];
		potential = new long[numNode];
		fill(potential, 0);
	}

	int addEdge(int source, int target, long cap, long cost) { // O(1)
		WeightedCapEdge e = new WeightedCapEdge(source, target, cap, cost, len[target]);
		len[source] ++;
		len[target] ++;
		edgesList.add(e);
		return numEdge ++;
	}

	void init() { // O(E)
		for(int i = 0; i < numNode; i ++) edges[i] = new WeightedCapEdge[len[i]];
		int idx[] = new int[numNode];
		for(WeightedCapEdge e : edgesList) {
			edges[e.target][idx[e.target] ++] = new WeightedCapEdge(e.target, e.source, 0, - e.cost, idx[e.source]);
			edges[e.source][idx[e.source] ++] = e;
		}
	}
	void clearFlow() { // O(V+E)
		fill(potential, 0);
		for(WeightedCapEdge e : edgesList) {
			long flow = e.getFlow();
			e.cap += flow;
			edges[e.target][e.rev].cap -= flow;
		}
	}

	// O(f(V+E)logV)
	PairLL minCostMaxFlow(int s, int t) { return minCostFlow(s, t, INF); }
	PairLL minCostFlow(int s, int t, long flowLimit) {
		PairLL[] slope = minCostSlope(s, t, flowLimit);
		return slope[slope.length - 1];
	}
	PairLL[] minCostSlope(int s, int t) { return minCostSlope(s, t, INF); }
	PairLL[] minCostSlope(int s, int t, long flowLimit) {
		if(s == t) return null;
		init();
		List<PairLL> slopeList = new ArrayList<>();
		long prvCost = -1;
		long flow = 0;
		long cost = 0;
		while(true) {
			slopeList.add(new PairLL(flow, cost));
			PairLL add = dijkstra(s, t, flowLimit - flow);
			if(add.a == 0) break;
			flow += add.a;
			cost += add.a * add.b;
			if(add.b == prvCost) slopeList.remove(slopeList.size() - 1);
			prvCost = add.b;
		}
		PairLL slope[] = new PairLL[slopeList.size()];
		for(int i = 0; i < slopeList.size(); i ++) slope[i] = slopeList.get(i);
		return slope;
	}
	PairLL dijkstra(int s, int t, long maxFlow) { // O((V+E)logV)
		long dist[] = new long[numNode];
		fill(dist, INF);
		dist[s] = 0;
		WeightedCapEdge prv[] = new WeightedCapEdge[numNode];

		Queue<Edge> pq = new PriorityQueue<>();
		pq.add(new Edge(s, s, dist[s]));
		while(!pq.isEmpty()) {
			Edge crt = pq.poll();
			if(dist[crt.target] < crt.cost) continue;
			for(WeightedCapEdge e : edges[crt.target]) {
				if(e.cap <= 0) continue;
				long cost = dist[e.source] + e.cost + potential[e.source] - potential[e.target];
				if(dist[e.target] > cost) {
					dist[e.target] = cost;
					prv[e.target] = e;
					pq.add(new Edge(e.source, e.target, dist[e.target]));
				}
			}
		}
		if(dist[t] == INF) return new PairLL(0, INF);
		for(int i = 0; i < numNode; i ++) potential[i] += dist[i];
		PairLL add = new PairLL(maxFlow, 0);
		for(int v = t; v != s; ) {
			WeightedCapEdge e = prv[v];
			add.b += e.cost;
			add.a = min(add.a, e.cap);
			v = e.source;
		}
		for(int v = t; v != s;) {
			WeightedCapEdge e = prv[v];
			e.cap -= add.a;
			edges[v][e.rev].cap += add.a;
			v = e.source;
		}
		return add;
	}
}


	}
}

class Main {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner();
        FastPrintStream pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(FastScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        long[][] a = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = sc.nextLong();
            }
        }
        Digraph<CapEdge> dig = new Digraph<>(n * n + 2 * n + 2);
        int s = n * n + 2 * n;
        int t = s + 1;
        int r = n * n;
        int c = n * n + n;
        for (int i = 0; i < n; i++) {
            dig.addEdge(new CapEdge(s, r + i, k, 0));
            dig.addEdge(new CapEdge(c + i, t, k, 0));
        }
        long INF = 1l << 50;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dig.addEdge(new CapEdge(r + i, i * n + j, 1, INF - a[i][j]));
                dig.addEdge(new CapEdge(i * n + j, c + j, 1, 0));
            }
        }
        long maxf = 0;
        long max = 0;
        MinCostFlow mcf = new MinCostFlow(dig);
        var slope = mcf.minCostSlope(s, t);
        for (var e : slope) {
            long flow = e[0];
            long cost = e[1];
            long x = flow * INF - cost;
            if (x > max) {
                max = x;
                maxf = flow;
            }
        }
        mcf.clearFlow();
        mcf.minCostFlow(s, t, maxf);
        pw.println(max);
        char[][] g = new char[n][n];
        for (char[] gi : g) java.util.Arrays.fill(gi, '.');
        for (CapEdge e : dig.getEdges()) {
            int u = e.from;
            int v = e.to;
            if (u == s || v == t || mcf.getFlow(e) == 0) continue;
            int i, j;
            if (u < n * n) {
                i = u / n;
                j = u % n;
            } else {
                i = v / n;
                j = v % n;
            }
            g[i][j] = 'X';
        }
        for (char[] gi : g) pw.println(gi);
    }
}

class MinCostFlow {
    private static final long INF = Long.MAX_VALUE;

    private final Digraph<CapEdge> dig;
    private final int n;
    private final int[] count;
    private final CapEdge[][] g;
    private final long[] potential;

    private final long[] dist;
    private final CapEdge[] prev;

    public MinCostFlow(Digraph<CapEdge> capDiraph) {
        this.dig = capDiraph;
        this.n = capDiraph.getV();
        this.count = new int[n];
        this.g = new CapEdge[n][];
        this.potential = new long[n];
        this.dist = new long[n];
        this.prev = new CapEdge[n];
        buildGraph();
    }

    private void buildGraph() {
        int[] idx = new int[n];
        for (int i = 0; i < n; i++) {
            count[i] = idx[i] = dig.deg(i);
        }
        for (CapEdge e : dig.getEdges()) {
            int j = e.to;
            count[j]++;
        }
        for (int i = 0; i < n; i++) {
            g[i] = new CapEdge[count[i]];
        }
        for (int u = 0; u < n; u++) {
            int k = dig.deg(u);
            for (int i = 0; i < k; i++) {
                CapEdge e = dig.getEdge(u, i);
                int v = e.to;
                e.rev = idx[v]++;
                CapEdge r = new CapEdge(v, u, 0, -e.cost);
                r.rev = i;
                g[u][i] = e;
                g[v][e.rev] = r;
            }
        }
    }

    public long getFlow(CapEdge e) {
        return g[e.to][e.rev].cap;
    }

    private long addFlow;
    private long addCost;

    public long[] minCostMaxFlow(int s, int t) {
        return minCostFlow(s, t, INF);
    }

    public long[] minCostFlow(int s, int t, long flowLimit) {
        rangeCheck(s, 0, n);
        rangeCheck(t, 0, n);
        if (s == t) {
            throw new IllegalArgumentException(String.format("s = t = %d", s));
        }
        nonNegativeCheck(flowLimit, "Flow");
        buildGraph();
        long flow = 0;
        long cost = 0;
        while (true) {
            dijkstra(s, t, flowLimit - flow);
            if (addFlow == 0) break;
            flow += addFlow;
            cost += addFlow * addCost;
        }
        return new long[]{flow, cost};
    }

    public java.util.ArrayList<long[]> minCostSlope(int s, int t) {
        return minCostSlope(s, t, INF);
    }

    public java.util.ArrayList<long[]> minCostSlope(int s, int t, long flowLimit) {
        rangeCheck(s, 0, n);
        rangeCheck(t, 0, n);
        if (s == t) {
            throw new IllegalArgumentException(String.format("s = t = %d", s));
        }
        nonNegativeCheck(flowLimit, "Flow");
        buildGraph();
        java.util.ArrayList<long[]> slope = new java.util.ArrayList<>();
        long prevCost = -1;
        long flow = 0;
        long cost = 0;
        while (true) {
            slope.add(new long[]{flow, cost});
            dijkstra(s, t, flowLimit - flow);
            if (addFlow == 0) return slope;
            flow += addFlow;
            cost += addFlow * addCost;
            if (addCost == prevCost) {
                slope.remove(slope.size() - 1);
            }
            prevCost = addCost;
        }
    }

    private void dijkstra(int s, int t, long maxFlow) {
        final class State implements Comparable<State> {
            final int v;
            final long d;
            State(int v, long d) {this.v = v; this.d = d;}
            public int compareTo(State s) {return d == s.d ? v - s.v : d > s.d ? 1 : -1;}
        }
        java.util.Arrays.fill(dist, INF);
        dist[s] = 0;
        java.util.PriorityQueue<State> pq = new java.util.PriorityQueue<>();
        pq.add(new State(s, 0l));
        while (pq.size() > 0) {
            State st = pq.poll();
            int u = st.v;
            if (st.d != dist[u]) continue;
            for (CapEdge e : g[u]) {
                if (e.cap <= 0) continue;
                int v = e.to;
                long nextCost = dist[u] + e.cost + potential[u] - potential[v];
                if (nextCost < dist[v]) {
                    dist[v] = nextCost;
                    prev[v] = e;
                    pq.add(new State(v, dist[v]));
                }
            }
        }
        if (dist[t] == INF) {
            addFlow = 0;
            addCost = INF;
            return;
        }
        for (int i = 0; i < n; i++) {
            potential[i] += dist[i];
        }
        addCost = 0;
        addFlow = maxFlow;
        for (int v = t; v != s;) {
            CapEdge e = prev[v];
            addCost += e.cost;
            addFlow = java.lang.Math.min(addFlow, e.cap);
            v = e.from;
        }
        for (int v = t; v != s;) {
            CapEdge e = prev[v];
            e.cap -= addFlow;
            g[v][e.rev].cap += addFlow;
            v = e.from;
        }
    }

    public void clearFlow() {
        java.util.Arrays.fill(potential, 0);
        for (CapEdge e : dig.getEdges()) {
            long flow = getFlow(e);
            e.cap += flow;
            g[e.to][e.rev].cap -= flow;
        }
    }

    private void rangeCheck(int i, int minInlusive, int maxExclusive) {
        if (i < 0 || i >= maxExclusive) {
            throw new IndexOutOfBoundsException(
                String.format("Index %d out of bounds for length %d", i, maxExclusive)
            );
        }
    }

    private void nonNegativeCheck(long cap, java.lang.String attribute) {
        if (cap < 0) {
            throw new IllegalArgumentException(
                String.format("%s %d is negative.", attribute, cap)
            );
        }
    }
}

class MaxFlow {
    private static final long INF = Long.MAX_VALUE;

    private final Digraph<CapEdge> dig;
    private final int n;
    private final int[] count;
    private final CapEdge[][] g;

    public MaxFlow(Digraph<CapEdge> capDiraph) {
        this.dig = capDiraph;
        this.n = capDiraph.getV();
        this.count = new int[n];
        this.g = new CapEdge[n][];
        buildGraph();
    }

    public long getFlow(CapEdge e) {
        return g[e.to][e.rev].cap;
    }

    public void changeEdge(int u, int i, long newCap, long newFlow) {
        nonNegativeCheck(newCap, "Capacity");
        if (newFlow > newCap) {
            throw new IllegalArgumentException(
                String.format("Flow %d is greater than capacity %d.", newCap, newFlow)
            );
        }
        CapEdge e = dig.getEdge(u, i);
        CapEdge er = g[e.to][e.rev];
        e.cap = newCap - newFlow;
        er.cap = newFlow;
    }

    private void buildGraph() {
        int[] idx = new int[n];
        for (int i = 0; i < n; i++) {
            count[i] = idx[i] = dig.deg(i);
        }
        for (CapEdge e : dig.getEdges()) {
            int j = e.to;
            count[j]++;
        }
        for (int i = 0; i < n; i++) {
            g[i] = new CapEdge[count[i]];
        }
        for (int u = 0; u < n; u++) {
            int k = dig.deg(u);
            for (int i = 0; i < k; i++) {
                CapEdge e = dig.getEdge(u, i);
                int v = e.to;
                e.rev = idx[v]++;
                CapEdge r = new CapEdge(v, u, 0);
                r.rev = i;
                g[u][i] = e;
                g[v][e.rev] = r;
            }
        }
    }

    public long maxFlow(int s, int t) {
        return flow(s, t, INF);
    }

    public long flow(int s, int t, long flowLimit) {
        rangeCheck(s, 0, n);
        rangeCheck(t, 0, n);
        buildGraph();
        long flow = 0;
        int[] level = new int[n];
        int[] que = new int[n];
        int[] iter = new int[n];
        while (true) {
            java.util.Arrays.fill(level, -1);
            dinicBFS(s, t, level, que);
            if (level[t] < 0) return flow;
            java.util.Arrays.fill(iter, 0);
            while (true) {
                long d = dinicDFS(t, s, flowLimit - flow, iter, level);
                if (d <= 0) break;
                flow += d;
            }
        }
    }

    private void dinicBFS(int s, int t, int[] level, int[] que) {
        int hd = 0, tl = 0;
        que[tl++] = s;
        level[s] = 0;
        while (tl > hd) {
            int u = que[hd++];
            for (CapEdge e : g[u]) {
                int v = e.to;
                if (e.cap <= 0 || level[v] >= 0) continue;
                level[v] = level[u] + 1;
                if (v == t) return;
                que[tl++] = v;
            }
        }
    }

    private long dinicDFS(int cur, int s, long f, int[] iter, int[] level) {
        if (cur == s) return f;
        long res = 0;
        while (iter[cur] < count[cur]) {
            CapEdge er = g[cur][iter[cur]++];
            int u = er.to;
            CapEdge e = g[u][er.rev];
            if (level[u] >= level[cur] || e.cap <= 0) continue;
            long d = dinicDFS(u, s, Math.min(f - res, e.cap), iter, level);
            if (d <= 0) continue;
            e.cap -= d;
            er.cap += d;
            res += d;
            if (res == f) break;
        }
        return res;
    }

    public long fordFulkersonMaxFlow(int s, int t) {
        return fordFulkersonFlow(s, t, INF);
    }

    public long fordFulkersonFlow(int s, int t, long flowLimit) {
        rangeCheck(s, 0, n);
        rangeCheck(t, 0, n);
        buildGraph();
        boolean[] used = new boolean[n];
        long flow = 0;
        while (true) {
            java.util.Arrays.fill(used, false);
            long f = fordFulkersonDFS(s, t, flowLimit - flow, used);
            if (f <= 0) return flow;
            flow += f;
        }
    }

    private long fordFulkersonDFS(int cur, int t, long f, boolean[] used) {
        if (cur == t) return f;
        used[cur] = true;
        for (CapEdge e : g[cur]) {
            if (used[e.to] || e.cap <= 0) continue;
            long d = fordFulkersonDFS(e.to, t, Math.min(f, e.cap), used);
            if (d <= 0) continue;
            e.cap -= d;
            g[e.to][e.rev].cap += d;
            return d;
        }
        return 0;
    }

    public boolean[] minCut(int s) {
        rangeCheck(s, 0, n);
        boolean[] reachable = new boolean[n];
        int[] stack = new int[n];
        int ptr = 0;
        stack[ptr++] = s;
        reachable[s] = true;
        while (ptr > 0) {
            int u = stack[--ptr];
            for (CapEdge e : g[u]) {
                int v = e.to;
                if (reachable[v] || e.cap <= 0) continue;
                reachable[v] = true;
                stack[ptr++] = v;
            }
        }
        return reachable;
    }

    private void rangeCheck(int i, int minInlusive, int maxExclusive) {
        if (i < 0 || i >= maxExclusive) {
            throw new IndexOutOfBoundsException(
                String.format("Index %d out of bounds for length %d", i, maxExclusive)
            );
        }
    }

    private void nonNegativeCheck(long cap, java.lang.String attribute) {
        if (cap < 0) {
            throw new IllegalArgumentException(
                String.format("%s %d is negative.", attribute, cap)
            );
        }
    }
}

abstract class AbstractGraph<Edg extends AbstractEdge> {
    final int n;
    final java.util.ArrayList<Edg> edges;
    final java.util.ArrayList<java.util.ArrayList<Edg>> adj;
    public AbstractGraph(int n) {
        this.n = n;
        this.edges = new java.util.ArrayList<>(n);
        this.adj = new java.util.ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new java.util.ArrayList<>());
        }
    }
    public abstract void addEdge(Edg edge);
    public Edg getEdge(int u, int i) {
        return adj.get(u).get(i);
    }
    public java.util.ArrayList<Edg> getEdges(int u) {
        return adj.get(u);
    }
    public java.util.ArrayList<Edg> getEdges() {
        return edges;
    }
    public int deg(int u) {
        return adj.get(u).size();
    }
    public int getV() {
        return n;
    }
    public int getE() {
        return edges.size();
    }
}

class Graph<Edg extends AbstractEdge> extends AbstractGraph<Edg> {
    public Graph(int n) {
        super(n);
    }
    @SuppressWarnings("unchecked")
    @Override
    public void addEdge(Edg edge) {
        Edg rev = (Edg) edge.reverse();
        adj.get(edge.from).add(edge);
        adj.get(edge.to).add(rev);
        edges.add(edge);
    }
}

class Digraph<Edg extends AbstractEdge> extends AbstractGraph<Edg> {
    public Digraph(int n) {
        super(n);
    }
    @Override
    public void addEdge(Edg edge) {
        adj.get(edge.from).add(edge);
        edges.add(edge);
    }
}

abstract class AbstractEdge implements Comparable<AbstractEdge> {
