		ACL.MinCostFlow flow = new ACL.MinCostFlow(2 * N + 2);
		final int START = 0, END = 2 * N + 1;
		final long MAX = 1000000001;
		IntBinaryOperator f = (x, y) -> x * N + y;
		int[] edge = new int[N * N + N + 1];
		for (int i = 1;i <= N;++ i) {
			flow.addEdge(START, i, K, 0);
			flow.addEdge(i + N, END, K, 0);
		}
