				int A = io.nextInt();
				edge[f.applyAsInt(x, y)] = flow.addEdge(x, y + N, 1, MAX - A);
			}
		}
		flow.addEdge(START, END, N * K, MAX);
		long[] ans = flow.minCostFlow(START, END, N * K);
		io.println(N * K * MAX - ans[1]);
		for (int y = 1;y <= N;++ y) {
			for (int x = 1;x <= N;++ x) {
				if (flow.getEdge(edge[f.applyAsInt(x, y)]).getFlow() != 0) io.print('X');
