public class MinCostFlowResult {
    public Weight TotalCost;
    public Weight TotalFlow;
}

public class PrimalDual {
    private readonly int N;
    private readonly List<List<Edge>> adjacents;

    private readonly Weight[] _distance;
    private readonly bool[] _inQueue;
    private readonly Edge[] _prevEdges;
    private readonly FastQueue<int> _queue;

    public class Edge {
        public int From, To;
        public Weight Flow, Capacity, Cost;
        public Edge Reverse;
        public Edge(int from, int to, Weight capacity, Weight cost, Weight flow = 0) {
            From = from;
            To = to;
            Cost = cost;
            Flow = flow;
            Capacity = capacity;
        }
        public Weight Residue {
            get {
                return Capacity - Flow;
            }
        }
    }

    public PrimalDual(int n) {
        N = n;
        adjacents = new List<List<Edge>>();
        for (int i = 0; i < n; i++) {
            adjacents.Add(new List<Edge>());
        }
        _distance = new Weight[N];
        _inQueue = new bool[N];
        _prevEdges = new Edge[N];
        _queue = new FastQueue<int>(N);
    }

    public IEnumerable<Edge> GetEdges() {
        return adjacents.SelectMany(a => a);
    }

    public void AddEdge(int from, int to, Weight capacity, Weight cost) {
        var e = new Edge(from, to, capacity, cost);
        adjacents[from].Add(e);
    }

    private Edge[] FindShortestPathTree(int source) {
        Array.Clear(_inQueue, 0, _inQueue.Length);
        Array.Clear(_prevEdges, 0, _prevEdges.Length);
        for (int i = 0; i < N; i++) {
            _distance[i] = Weight.MaxValue;
        }
        _distance[source] = 0;
        _inQueue[source] = true;
        _queue.Enqueue(source);
        while (_queue.Count > 0) { // SPFA
            int now = _queue.Dequeue();
            _inQueue[now] = false;
            foreach (var e in adjacents[now]) {
                if (e.Residue <= 0) {
                    continue;
                }

                if (_distance[now] != Weight.MaxValue && _distance[e.To] > _distance[now] + e.Cost) {
                    _distance[e.To] = _distance[now] + e.Cost;
                    _prevEdges[e.To] = e;
                    if (!_inQueue[e.To]) {
                        _inQueue[e.To] = true;
                        _queue.Enqueue(e.To);
                    }
                }
            }
        }
        return _prevEdges;
    }

    public MinCostFlowResult Run(int source, int sink, Weight flow) {
        Weight totalCost = 0;
        Weight totalFlow = 0;

        while (totalFlow < flow) {
            var prevEdges = FindShortestPathTree(source);
            if (prevEdges[sink] == null) {
                break;
            }
            long incrementalFlow = flow - totalFlow;
            for (var e = prevEdges[sink]; e != null; e = prevEdges[e.From]) {
                incrementalFlow = Math.Min(incrementalFlow, e.Residue);
            }
            for (var e = prevEdges[sink]; e != null; e = prevEdges[e.From]) {
                if (e.Reverse == null) {
                    var reverseEdge = new Edge(e.To, e.From, 0, -e.Cost) {
                        Reverse = e
                    };
                    e.Reverse = reverseEdge;
                    adjacents[e.To].Add(reverseEdge);
                }
                totalCost += e.Cost * incrementalFlow;
                e.Flow += incrementalFlow;
                e.Reverse.Flow -= incrementalFlow;
            }
            totalFlow += incrementalFlow;
        }
        return new MinCostFlowResult { TotalCost = totalCost, TotalFlow = totalFlow };
    }
}

public class FastQueue<T> {
    private T[] _array;
    private int _head;
    private int _tail;
    public int Count { get; private set; }

    public FastQueue(int capacity = 16) {
        _array = new T[capacity];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    private void Expand() {
        var newarray = new T[_array.Length * 2];

        if (_head < _tail) {
            Array.Copy(_array, _head, newarray, 0, Count);
        } else {
            Array.Copy(_array, _head, newarray, 0, _array.Length - _head);
            Array.Copy(_array, 0, newarray, _array.Length - _head, _tail);
        }

        _head = 0;
        _tail = Count == newarray.Length ? 0 : Count;
        _array = newarray;
    }

    public void Enqueue(T value) {
        if (Count + 1 == _array.Length) { // expand
            Expand();
        }
        Count++;
        _array[_tail++] = value;
        if (_tail == _array.Length) {
            _tail = 0;
        }
    }

    public T Peek() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        return _array[_head];
    }

    public T Dequeue() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        var ret = _array[_head++];
        Count--;
        if (_head == _array.Length) {
            _head = 0;
        }
        return ret;
    }
}
public class PriorityQueue<T> {
    private T[] _array = new T[128];
    private int _size = 0;
    private readonly Comparison<T> _compare;

    public PriorityQueue() {
        _compare = Comparer<T>.Default.Compare;
    }

    public PriorityQueue(Comparison<T> comp) {
        _compare = comp;
    }

    public int Count { get { return _size; } }

    private void Swap(int a, int b) {
        var t = _array[a];
        _array[a] = _array[b];
        _array[b] = t;
    }

    private void Expand() {
        var newlist = new T[_array.Length << 1];
        Array.Copy(_array, newlist, _array.Length);
        _array = newlist;
    }

    public bool Any() {
        return _size > 0;
    }

    public void Enqueue(T newValue) {
        int pos = ++_size;
        if (_size >= _array.Length) {
            Expand();
        }
        _array[pos] = newValue;
        while (pos > 1) {
            int parent = pos >> 1;
            if (_compare(_array[parent], _array[pos]) > 0) {
                Swap(parent, pos);
                pos = parent;
            } else {
                break;
            }
        }
    }

    public T Peek() {
        return _array[1];
    }

    public T Dequeue() {
        var top = _array[1];
        int pos = 1;
        _array[pos] = _array[_size--];
        while ((pos << 1) <= _size) {
            int left = pos << 1;
            int right = left | 1;
            int next = left;
            if (right <= _size && _compare(_array[left], _array[right]) > 0) {
                next = right;
            }
            if (_compare(_array[pos], _array[next]) > 0) {
                Swap(next, pos);
                pos = next;
            } else {
                break;
            }
        }

        return top;
    }
};

