namespace CompLib.Graph
{
    using System;
    using System.Collections.Generic;
    using System.Diagnostics;
    using Cap = System.Int32;
    class MaxFlow
    {
        private List<S> _pos;
        private List<InternalEdge>[] _g;
        private readonly int _n;
        private readonly int[] _level, _iter;

        private readonly int[] _queue;
        private int _begin, _end;
        public MaxFlow(int n)
        {
            _n = n;
            _g = new List<InternalEdge>[_n];
            for (int i = 0; i < _n; i++)
            {
                _g[i] = new List<InternalEdge>();
            }
            _pos = new List<S>();

            _level = new int[_n];
            _iter = new int[_n];

            _queue = new int[_n];
        }

        public int AddEdge(int from, int to, Cap cap)
        {
            Debug.Assert(0 <= from && from < _n);
            Debug.Assert(0 <= to && to < _n);
            Debug.Assert(0 <= cap);
            int m = _pos.Count;
            _pos.Add(new S(from, _g[from].Count));
            int fromID = _g[from].Count;
            int toID = _g[to].Count;
            if (from == to) toID++;
            _g[from].Add(new InternalEdge(to, toID, cap));
            _g[to].Add(new InternalEdge(from, fromID, 0));
            return m;
        }

        public Edge GetEdge(int i)
        {
            int m = _pos.Count;
            Debug.Assert(0 <= i && i < m);
            var e = _g[_pos[i].From][_pos[i].Index];
            var re = _g[e.To][e.Rev];

            return new Edge(_pos[i].From, e.To, e.Cap + re.Cap, re.Cap);
        }

        public Edge[] Edges()
        {
            int m = _pos.Count;
            Edge[] result = new Edge[m];
            for (int i = 0; i < m; i++)
            {
                result[i] = GetEdge(i);
            }
            return result;
        }

        public void ChangeEdge(int i, Cap newCap, Cap newFlow)
        {
            int m = _pos.Count;
            Debug.Assert(0 <= i && i < m);
            Debug.Assert(0 <= newFlow && newFlow <= newCap);
            var e = _g[_pos[i].From][_pos[i].Index];
            var re = _g[e.To][e.Rev];
            e.Cap = newCap - newFlow;
            re.Cap = newFlow;
            _g[_pos[i].From][_pos[i].Index] = e;
            _g[e.To][e.Rev] = re;
        }

        private void BFS(int s, int t)
        {
            for (int i = 0; i < _n; i++)
            {
                _level[i] = -1;
            }
            _level[s] = 0;
            _begin = 0;
            _end = 0;
            _queue[_end++] = s;
            while (_end > _begin)
            {
                int v = _queue[_begin++];
                foreach (var e in _g[v])
                {
                    if (e.Cap == 0 || _level[e.To] >= 0) continue;
                    _level[e.To] = _level[v] + 1;
                    if (e.To == t) return;
                    _queue[_end++] = e.To;
                }
            }
        }

        private Cap DFS(int v, int s, Cap up)
        {
            if (v == s) return up;
            Cap res = 0;
            for (; _iter[v] < _g[v].Count; _iter[v]++)
            {
                var e = _g[v][_iter[v]];
                if (_level[v] <= _level[e.To] || _g[e.To][e.Rev].Cap == 0) continue;
                Cap d = DFS(e.To, s, Math.Min(up - res, _g[e.To][e.Rev].Cap));
                if (d <= 0) continue;

                e.Cap += d;
                _g[v][_iter[v]] = e;

                var rev = _g[e.To][e.Rev];
                rev.Cap -= d;
                _g[e.To][e.Rev] = rev;
                res += d;
                if (res == up) break;
            }
            return res;
        }

        public Cap Flow(int s, int t, Cap flowLimit)
        {
            Debug.Assert(0 <= s && s < _n);
            Debug.Assert(0 <= t && t < _n);
            Debug.Assert(s != t);


            Cap flow = 0;
            while (flow < flowLimit)
            {
                BFS(s, t);
                if (_level[t] == -1) break;
                for (int i = 0; i < _n; i++)
                {
                    _iter[i] = 0;
                }
                while (flow < flowLimit)
                {
                    Cap f = DFS(t, s, flowLimit - flow);
                    if (f == 0) break;
                    flow += f;
                }
            }

            return flow;
        }


        public Cap Flow(int s, int t)
        {
            return Flow(s, t, Cap.MaxValue);
        }

        public bool[] MinCut(int s)
        {
            bool[] visited = new bool[_n];
            _begin = 0;
            _end = 0;
            _queue[_end++] = s;
            visited[s] = true;
            while (_end > _begin)
            {
                var p = _queue[_begin++];
                foreach (var e in _g[p])
                {
                    if (e.Cap > 0 && !visited[e.To])
                    {
                        visited[e.To] = true;
                        _queue[_end++] = e.To;
                    }
                }
            }
            return visited;
        }

        struct InternalEdge
        {
            public int To, Rev;
            public Cap Cap;
            public InternalEdge(int to, int rev, Cap cap)
            {
                To = to;
                Rev = rev;
                Cap = cap;
            }
        }

        struct S
        {
            public readonly int From, Index;
            public S(int from, int index)
            {
                From = from;
                Index = index;
            }
        }
    }

    public struct Edge
    {
        public readonly int From, To;
        public readonly Cap Cap, Flow;
        public Edge(int from, int to, Cap cap, Cap flow)
        {
            From = from;
            To = to;
            Cap = cap;
            Flow = flow;
        }
    }
}


