public class Mcfp{
	private List<int>[] li;
	private Eg[] h;
	private nint[][] pt;
	private int[] l,r;
	private nint[] z,u;
	private bool[] b1,b2;
	private int n,p=0;
	private const nint inf=nint.MaxValue;
	public class Eg{
		public int n;
		public nint e,c;
		public Eg(int n,nint e,nint c){this.n=n;this.e=e;this.c=c;}
	}
	public Mcfp(int n,int m){
		this.n=n;
		m<<=1;
		li=new List<int>[n];
		z=new nint[n];
		l=new int[n];
		r=new int[n];
		u=new nint[n];
		h=new Eg[m];
		for(int i=0;i<n;i++){
			li[i]=new List<int>();
			z[i]=u[i]=inf;
		}
	}
	public void Edge(int a,int b,int e,nint c){
		if(a==b){return;}
		li[a].Add(p);
		li[b].Add(p+1);
		h[p]=new Eg(b,e,c);
		h[p+1]=new Eg(a,0,-c);
		p+=2;
	}
	public long Pd1(int s,int t,int c){
		long ans=0,d=0;
		pt=new nint[][]{new nint[n],new nint[n]};
		int k=0;
		while(c>d){
			b1=new bool[n];
			b2=new bool[n];
			var pq=new Rheap<int>(32);
			z[s]=0;
			l[s]=-1;
			b2[s]=true;
			pq.Push(new Rheap<int>.Dt(0,s));
			bool bo=false;
			while(pq.cnt>0){
				var e=pq.Dequeue;
				if(b1[e.d]){continue;}
				b1[e.d]=true;
				if(e.d==t){bo=true;}
				for(int i=0;i<li[e.d].Count;i++){
					if(h[li[e.d][i]].e==0){continue;}
					nint co=e.n+h[li[e.d][i]].c-pt[k^1][h[li[e.d][i]].n]+pt[k^1][e.d];
					if(!b2[h[li[e.d][i]].n]||z[h[li[e.d][i]].n]>co){
						b2[h[li[e.d][i]].n]=true;
						z[h[li[e.d][i]].n]=co;
						pt[k][h[li[e.d][i]].n]=pt[k^1][h[li[e.d][i]].n]+co;
						l[h[li[e.d][i]].n]=e.d;
						r[h[li[e.d][i]].n]=li[e.d][i];
						u[h[li[e.d][i]].n]=Min(u[e.d],h[li[e.d][i]].e);
						pq.Push(new Rheap<int>.Dt(z[h[li[e.d][i]].n],h[li[e.d][i]].n));
					}
					else if(z[h[li[e.d][i]].n]==co){
						var o=Min(u[e.d],h[li[e.d][i]].e);
						if(u[h[li[e.d][i]].n]<o){
							u[h[li[e.d][i]].n]=o;
							l[h[li[e.d][i]].n]=e.d;
							r[h[li[e.d][i]].n]=li[e.d][i];
						}
					}
				}
			}
			if(!bo){break;}
			u[t]=(int)Min(c-d,u[t]);
			for(int i = t;i!=s;i=l[i]) {
				ans+=u[t]*h[r[i]].c;
				h[r[i]].e-=u[t];
				h[r[i]^1].e+=u[t];
			}
			k^=1;
			d+=u[t];
		}
		return c==d?ans:-1;
	}
	public long Pd2(int s,int t,int c){
		long ans=0,d=0;
		z[s]=0;
