			if(!bo){break;}
			u[t]=(int)Min(c-d,u[t]);
			for(int i = t;i!=s;i=l[i]) {
				ans+=u[t]*h[r[i]].c;
				h[r[i]].e-=u[t];
				h[r[i]^1].e+=u[t];
