public class Program
{

    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int k = sc.NextInt();
        int[][] a = new int[n][];
        for (int i = 0; i < n; i++)
        {
            a[i] = sc.IntArray();
        }

        // 0スタート
        // 1~n^2 各マス
        // n^2+1~n^2+n 縦
        // 横
        // ゴール


        const long inf = 1000000000;
        var mcf = new MinCostFlow(1 + 2 * n + 1);
        int s = 2 * n;
        int g = 1 + 2 * n;
        mcf.AddEdge(s, g, n * k, inf);
        for (int i = 0; i < n; i++)
        {
            mcf.AddEdge(s, i, k, 0);
            mcf.AddEdge(n + i, g, k, 0);
        }
        var ls = new List<int>();
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                ls.Add(mcf.AddEdge(i, n + j, 1, inf - a[i][j]));
            }
        }

        var res = mcf.Flow(s, g, n * k);
        long max = (long)n * k * inf - res.Cost;
        Console.WriteLine(max);
        char[][] ans = new char[n][];
        for (int i = 0; i < n; i++)
        {
            ans[i] = new char[n];
            for (int j = 0; j < n; j++)
            {
                ans[i][j] = '.';
            }
        }
        foreach (var i in ls)
        {
            var e = mcf.GetEdge(i);
            if (e.Flow > 0)
            {
                ans[e.From][e.To - n] = 'X';
            }
        }
        for (int i = 0; i < n; i++)
        {
            Console.WriteLine(new string(ans[i]));
        }
    }

    public static void Main(string[] args) => new Program().Solve();
    // public static void Main(string[] args) => new Thread(new Program().Solve, 1 << 27).Start();
}

