class PrimalDual
{
    const long Inf = long.MaxValue/2;
    List<_Edge> edges;
    public int EdgeCount => edges.Count;
    List<int>[] G;
    public PrimalDual(int N)
    {
        G = Create(N, () => new List<int>());
        edges = new List<_Edge>();
    }
    public void AddEdge(int from, int to, long cap, long cost)
    {
        int edgeIndex = edges.Count;
        G[from].Add(edgeIndex);
        edges.Add(new _Edge(to, edgeIndex, cap, cost));
        G[to].Add(edgeIndex | 1);
        edges.Add(new _Edge(from, edgeIndex | 1, 0, -cost));
    }
    public Edge GetEdge(int i) => new Edge { from = edges[i ^ 1].to, to = edges[i].to, cap = edges[i].cap + edges[i ^ 1].cap, flow = edges[i ^ 1].cap, cost = edges[i].cost };
    //flow,cost
    public (long, long) flow(int s, int t, long f = Inf) => Slope(s, t, f).Last();
    public List<(long,long)> Slope(int s,int t,long f)
    {
        int N = G.Length;
        var dual = new long[N];var dist = new long[N];//cost
        var pv = new int[N];var pe = new int[N];//最短経路木のようなもの
        var used = new bool[N];
        Func<bool> SP = null;
        SP = () =>
        {
            for (int i = 0; i < dist.Length; i++)
            {
                dist[i] = Inf;
                pv[i] = pe[i] = -1;
                used[i] = false;
            }
            var pq = new PriorityQueue<(long dist, int to)>((a, b) => a.dist.CompareTo(b.dist));
            dist[s] = 0;
            pq.Push((0, s));
            while (pq.Any())
            {
                var v = pq.Pop().to;
                if (used[v]) continue;
                used[v] = true;
                if (v == t) break;
                for (int i = 0; i < G[v].Count; i++)
                {
                    var e = edges[G[v][i]];
                    if (used[e.to] || e.cap == 0) continue;
                    var cost = e.cost - dual[e.to] + dual[v];
                    if (dist[e.to] - dist[v] > cost)
                    {
                        dist[e.to] = dist[v] + cost;
                        pv[e.to] = v;
                        pe[e.to] = e.idx;
                        pq.Push((dist[e.to], e.to));
                    }
                }
            }
            if (!used[t]) return false;
            for (int i = 0; i < dist.Length; i++)
            {
                if (!used[i]) continue;
                dual[i] = dist[t] - dist[i];//ポテンシャル
            }
            return true;
        };
        long flow = 0, cost = 0, prev = -1;
        var res = new List<(long, long)>();
        res.Add((flow, cost));
        while (flow < f)
        {
            if (!SP()) break;
            var c = f - flow;
            for (var v = t; v != s; v = pv[v]) c = Min(c, edges[pe[v]].cap);
            for(int v = t; v != s; v = pv[v])
            {
                edges[pe[v]].cap -= c;
                edges[pe[v] ^ 1].cap += c;
            }
            var d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev == d) res.RemoveAt(res.Count - 1);
            res.Add((flow, cost));
            prev = d;
        }
        return res;
    }
    public struct Edge { public int from,to; public long cap, cost, flow; }
    public class _Edge
    {
        public int to, idx;
        public long cap, cost;
        public _Edge(int t,int i,long ca,long co)
        {
            to = t;idx = i;cap = ca;cost = co;
        }
    }
}

public class PriorityQueue<T>
{
    private List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
}

