	public class Program
	{
		static void Main()
		{
			using var cin = new Scanner();
			var (n, k) = cin.Int2();
			var a = new long[n, n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					a[i, j] = cin.Long();
				}
			}

			long inf = 1000000000;
			int si = n * 2;
			int ti = n * 2 + 1;
			var flow = new McfGraphLong(n * 2 + 2);
			flow.AddEdge(si, ti, n * k, inf);
			for (int i = 0; i < n; i++) {
				flow.AddEdge(si, i, k, 0);
				flow.AddEdge(i + n, ti, k, 0);
			}

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					flow.AddEdge(i, j + n, 1, inf - a[i, j]);
				}
			}

			var ret = flow.Flow(si, ti, n * k);
			Console.WriteLine(n * k * inf - ret.cost);

			var ans = new char[n][];
			for (int i = 0; i < n; i++) {
				ans[i] = new char[n];
			}

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					ans[i][j] = '.';
				}
			}

			var edges = flow.Edges();
			foreach (var e in edges) {
				if (e.From == si || e.To == ti || e.Flow == 0) {
					continue;
				}

				ans[e.From][e.To - n] = 'X';
			}

			for (int i = 0; i < n; i++) {
				Console.WriteLine(new string(ans[i]));
			}
		}
	}

