	mcf.pos = append(mcf.pos, [2]int{from, len(mcf.g[from])})
	mcf.g[from] = append(mcf.g[from], _minCostFlowEdge{to, len(mcf.g[to]), capa, cost})
	mcf.g[to] = append(mcf.g[to], _minCostFlowEdge{from, len(mcf.g[from]) - 1, 0, -cost})
	return m
}

func (mcf *MinCostFlow) GetEdge(i int) MinCostFlowEdge {
	m := len(mcf.pos)
	mcf.assert(0 <= i && i < m)
	e := mcf.g[mcf.pos[i][0]][mcf.pos[i][1]]
	re := mcf.g[e.to][e.rev]
	return MinCostFlowEdge{mcf.pos[i][0], e.to, e.capa + re.capa, re.capa, e.cost}
}

func (mcf *MinCostFlow) Edges() []MinCostFlowEdge {
	m := len(mcf.pos)
	res := make([]MinCostFlowEdge, m)
	for i := range res {
		res[i] = mcf.GetEdge(i)
	}
	return res
}

func (mcf *MinCostFlow) Flow(s, t int) (int, int) {
	sl := mcf.Slope(s, t)
	n := len(sl) - 1
	return sl[n][0], sl[n][1]
}

func (mcf *MinCostFlow) FlowWithLimit(s, t, flowLimit int) (int, int) {
	sl := mcf.SlopeWithLimit(s, t, flowLimit)
	n := len(sl) - 1
	return sl[n][0], sl[n][1]
}

func (mcf *MinCostFlow) Slope(s, t int) [][2]int {
	return mcf.SlopeWithLimit(s, t, 1e9+10)
}

type _minCostFlowQueueElm struct {
	key int
	to  int
}

type _minCostFlowQueueSlice struct {
	a []_minCostFlowQueueElm
}

func newMinCostFlowQueueSlice() *_minCostFlowQueueSlice {
	return &_minCostFlowQueueSlice{
		a: make([]_minCostFlowQueueElm, 0),
	}
}

func (s *_minCostFlowQueueSlice) Len() int {
	return len(s.a)
}

func (s *_minCostFlowQueueSlice) Less(i, j int) bool {
	return s.a[i].key < s.a[j].key
}

func (s *_minCostFlowQueueSlice) Swap(i, j int) {
	s.a[i], s.a[j] = s.a[j], s.a[i]
}

func (s *_minCostFlowQueueSlice) Push(x interface{}) {
	e := x.(_minCostFlowQueueElm)
	s.a = append(s.a, e)
}

func (s *_minCostFlowQueueSlice) Pop() interface{} {
	n := len(s.a) - 1
	e := s.a[n]
	s.a = s.a[:n]
	return e
}

func (mcf *MinCostFlow) SlopeWithLimit(s, t, flowLimit int) [][2]int {
	mcf.assert(0 <= s && s < mcf.n)
	mcf.assert(0 <= t && t < mcf.n)
	mcf.assert(s != t)

	dual := make([]int, mcf.n)
	dist := make([]int, mcf.n)
	pv := make([]int, mcf.n)
	pe := make([]int, mcf.n)
	vis := make([]bool, mcf.n)
	dualRef := func() bool {
		for i := range dual {
			dist[i] = 1e9 + 10
			pv[i] = -1
			pe[i] = -1
			vis[i] = false
		}
		que := newMinCostFlowQueueSlice()
		heap.Init(que)
		que_push := func(cost, to int) {
			dbg("que_push(", cost, to, ")")
			elm := _minCostFlowQueueElm{cost, to}
			heap.Push(que, elm)
		}
		que_pop := func() int {
			x := heap.Pop(que)
			elm := x.(_minCostFlowQueueElm)
			dbg("que_pop() -> ", elm.to)
			return elm.to
		}
		dist[s] = 0
		que_push(0, s)
		for que.Len() != 0 {
			dbg("loop")
			dbg("que", que.a)
			v := que_pop()
			dbg("v", v)
			if vis[v] {
				dbg("v is visited")
				continue
			}
			vis[v] = true
			if v == t {
				dbg("v equal t")
				break
			}
			dbg("mid")
			for i := 0; i < len(mcf.g[v]); i++ {
				e := mcf.g[v][i]
				if vis[e.to] || e.capa == 0 {
					continue
				}
				dbg("e", e)
				cost := e.cost - dual[e.to] + dual[v]
				dbg("cost", cost)
				if dist[e.to]-dist[v] > cost {
					dist[e.to] = dist[v] + cost
					pv[e.to] = v
					pe[e.to] = i
					que_push(dist[e.to], e.to)
				}
			}
		}
		if !vis[t] {
			return false
		}
		for v := 0; v < mcf.n; v++ {
			if !vis[v] {
				continue
			}
			dual[v] -= dist[t] - dist[v]
		}
		return true
	}

	var flow, cost int
	prevCost := -1
	result := make([][2]int, 0)
	result = append(result, [2]int{flow, cost})
	for flow < flowLimit {
		if !dualRef() {
			break
		}
		c := flowLimit - flow
		for v := t; v != s; v = pv[v] {
			c = mcf.min(c, mcf.g[pv[v]][pe[v]].capa)
		}
		for v := t; v != s; v = pv[v] {
			e := &mcf.g[pv[v]][pe[v]]
			e.capa -= c
			mcf.g[v][e.rev].capa += c
		}
		d := -dual[s]
		flow += c
		cost += c * d
		if prevCost == d {
			result = result[:len(result)-1]
		}
		result = append(result, [2]int{flow, cost})
		prevCost = cost
	}
	return result
}

func (mcf *MinCostFlow) MinCut(s int) []bool {
	visited := make([]bool, mcf.n)

	que := make([]int, 0)
	que_empty := func() bool {
		return len(que) == 0
	}
	que_push := func(v int) {
		que = append(que, v)
	}
	que_pop := func() int {
		v := que[0]
		que = que[1:]
		return v
	}

	que_push(s)
	for !que_empty() {
		p := que_pop()
		visited[p] = true
		for _, e := range mcf.g[p] {
			if 0 < e.capa && !visited[e.to] {
				visited[e.to] = true
				que_push(e.to)
			}
		}
	}
	return visited
}

