type MinCostFlowEdge struct {
	From, To   int
	Capa, Flow int
	Cost       int
}

type _minCostFlowEdge struct {
	to, rev int
	capa    int
	cost    int
}

type MinCostFlow struct {
	n   int
	pos [][2]int
	g   [][]_minCostFlowEdge
}

type _minCostFlowQueueElm struct {
	key int
	to  int
}

type _minCostFlowQueueSlice struct {
	a []_minCostFlowQueueElm
