func (mcf *MinCostFlow) SlopeWithLimit(s, t, flowLimit int) [][2]int {
	mcf.assert(0 <= s && s < mcf.n)
	mcf.assert(0 <= t && t < mcf.n)
	mcf.assert(s != t)

	dual := make([]int, mcf.n)
	dist := make([]int, mcf.n)
	pv := make([]int, mcf.n)
	pe := make([]int, mcf.n)
	vis := make([]bool, mcf.n)
	dualRef := func() bool {
		for i := range dual {
			dist[i] = 1e9 + 10
			pv[i] = -1
			pe[i] = -1
			vis[i] = false
		}
		que := newMinCostFlowQueueSlice()
		heap.Init(que)
		que_push := func(cost, to int) {
			elm := _minCostFlowQueueElm{cost, to}
			heap.Push(que, elm)
		}
		que_pop := func() int {
			x := heap.Pop(que)
			elm := x.(_minCostFlowQueueElm)
			return elm.to
		}
		dist[s] = 0
		que_push(0, s)
		for que.Len() != 0 {
			v := que_pop()
			if vis[v] {
				continue
			}
			vis[v] = true
			if v == t {
				break
			}
			for i := 0; i < len(mcf.g[v]); i++ {
				e := mcf.g[v][i]
				if vis[e.to] || e.capa == 0 {
					continue
				}
				cost := e.cost - dual[e.to] + dual[v]
				if dist[e.to]-dist[v] > cost {
					dist[e.to] = dist[v] + cost
					pv[e.to] = v
					pe[e.to] = i
					que_push(dist[e.to], e.to)
				}
			}
		}
		if !vis[t] {
			return false
		}
		for v := 0; v < mcf.n; v++ {
			if !vis[v] {
				continue
			}
			dual[v] -= dist[t] - dist[v]
		}
		return true
	}

	var flow, cost int
	prevCost := -1
	result := make([][2]int, 0)
	result = append(result, [2]int{flow, cost})
	for flow < flowLimit {
		if !dualRef() {
			break
		}
		c := flowLimit - flow
		for v := t; v != s; v = pv[v] {
			c = mcf.min(c, mcf.g[pv[v]][pe[v]].capa)
		}
		for v := t; v != s; v = pv[v] {
			e := &mcf.g[pv[v]][pe[v]]
			e.capa -= c
			mcf.g[v][e.rev].capa += c
		}
		d := -dual[s]
		flow += c
		cost += c * d
		if prevCost == d {
			result = result[:len(result)-1]
		}
		result = append(result, [2]int{flow, cost})
		prevCost = cost
	}
	return result
}

func (mcf *MinCostFlow) MinCut(s int) []bool {
	visited := make([]bool, mcf.n)

	que := make([]int, 0)
	que_empty := func() bool {
		return len(que) == 0
	}
	que_push := func(v int) {
		que = append(que, v)
	}
	que_pop := func() int {
		v := que[0]
		que = que[1:]
		return v
	}

	que_push(s)
	for !que_empty() {
		p := que_pop()
		visited[p] = true
		for _, e := range mcf.g[p] {
			if 0 < e.capa && !visited[e.to] {
				visited[e.to] = true
				que_push(e.to)
			}
		}
	}
	return visited
}

// Setup OutputBuffer and OutputWriter.
func SetOutput(w io.Writer) {
	OutputBuffer = bufio.NewWriter(w)
	OutputWriter = OutputBuffer
}

// Flushes OutputBuffer
func Flush() {
	if OutputBuffer != nil {
		OutputBuffer.Flush()
	}
}

// Returns true if c is a white space
func IsSpace(c byte) bool {
	switch c {
	case '\t', '\n', '\v', '\f', '\r', ' ':
		return true
	}
	return false
}

func IsNewLine(c byte) bool {
	switch c {
	case '\n', '\r':
		return true
	}
	return false
}

// Setup nextToken with input buffer.
func SetInput(r io.Reader) {
	buf := new(bytes.Buffer)
	var b []byte

	var i int
	rest := func() ([]byte, error) {
		for i < len(b) && IsSpace(b[i]) {
			i++
		}
		if i == len(b) {
			return nil, io.ErrUnexpectedEOF
		}
		j := i
		for i < len(b) && !IsSpace(b[i]) {
			i++
		}
		return b[j:i], nil
	}
	initial := func() ([]byte, error) {
		io.Copy(buf, r)
		b = buf.Bytes()
		nextToken = rest
		return rest()
	}
	nextToken = initial

	restLn := func() ([]byte, error) {
		for i < len(b) && IsNewLine(b[i]) {
			i++
		}
		if i == len(b) {
			return nil, io.ErrUnexpectedEOF
		}
		j := i
		for i < len(b) && !IsNewLine(b[i]) {
			i++
		}
		return b[j:i], nil
	}

	initialLn := func() ([]byte, error) {
		io.Copy(buf, r)
		b = buf.Bytes()
		nextLine = restLn
		return restLn()
	}
	nextLine = initialLn
}

// Reads next token and return it as []byte
func readb() []byte {
	b, err := nextToken()
	if err != nil {
		panic(err)
	}
	return b[:len(b):len(b)]
}

// Reads next token and return it as string
func reads() string {
	return string(readb())
}

// Reads next token and return it as int64
func readll() int64 {
	i, err := strconv.ParseInt(reads(), 10, 64)
	if err != nil {
		panic(err.Error())
	}
	return i
}

// Reads next token and return it as int
func readi() int {
	return int(readll())
}

// Write args to OutputWriter without format
func println(args ...interface{}) (int, error) {
	return fmt.Fprintln(OutputWriter, args...)
}
