proc flow*[Cap, Cost](self: var McfGraph[Cap, Cost]; s, t: int): tuple[cap: Cap, cost: Cost] =
  let x = self.cFlow(s, t)
  result.cap = x.first
  result.cost = x.second
proc flow*[Cap, Cost](self: var McfGraph[Cap, Cost]; s, t: int; flowLimit: Cap): tuple[cap: Cap, cost: Cost] =
  let x = self.cFlow(s, t, flowLimit)
  result.cap = x.first
