fn main() {
    let v = read_vec::<usize>();
    let (n, k) = (v[0], v[1] as i64);
    let mut a = vec![vec![]; n];
    for i in 0..n {
        a[i] = read_vec::<i64>();
    }

    let mut flow = MinCostFlowGraph::<i64>::new(2 * n + 4);
    let s = 2 * n;
    let s0 = 2 * n + 1;
    let t0 = 2 * n + 2;
    let t = 2 * n + 3;

    flow.add_edge(s, s0, (n * n) as i64, 0);
    flow.add_edge(t0, t, (n * n) as i64, 0);

    for y in 0..n {
        flow.add_edge(s0, y, k, 0);
    }
    for x in 0..n {
        flow.add_edge(x + n, t0, k, 0);
    }

    let inf = 1000000000i64;

    for y in 0..n {
        for x in 0..n {
            flow.add_edge(y, x + n, 1, inf - a[y][x]);
        }
    }

    let mut flow2 = flow.clone();
    let mut max_flow = 0;
    for i in 1..n * n + 1 {
        let (ma, min_cost) = flow.flow(s, t, 1);
        if min_cost > inf || ma == 0 {
            break;
        }
        max_flow = i;
    }
    let (_, min_cost) = flow2.flow(s, t, max_flow as i64);
    println!("{}", inf * max_flow as i64 - min_cost);

    let mut grid = vec![vec!['.'; n]; n];
    for edge in flow2.edges() {
        if edge.to >= 2 * n {
            continue;
        }
        if edge.from >= 2 * n {
            continue;
        }
        if edge.cap >= 1 {
            continue;
        }
        let x = edge.from;
        let y = edge.to - n;
        grid[y][x] = 'X';
    }

    for line in grid {
        for ch in line {
            print!("{}", ch);
        }
        println!("");
    }
}

