        fn min_value() -> Self;
        fn max_value() -> Self;
    }

    macro_rules! impl_integral {
        ($($ty:ty),*) => {
            $(
                impl Integral for $ty {
                    #[inline]
                    fn zero() -> Self {
                        0
                    }

                    #[inline]
