fn main() {
    let v = read_vec::<usize>();
    let (n, k) = (v[0], v[1] as i64);
    let mut a = vec![vec![]; n];
    for i in 0..n {
        a[i] = read_vec::<i64>();
    }

    let mut flow = MinCostFlowGraph::<i64>::new(2 * n + 2);
    let s = 2 * n;
    let t = 2 * n + 1;

    let inf = 1000000000i64;

    flow.add_edge(s, t, n as i64 * k, inf);

    for y in 0..n {
        flow.add_edge(s, y, k, 0);
    }
    for x in 0..n {
        flow.add_edge(x + n, t, k, 0);
    }

    for y in 0..n {
        for x in 0..n {
            flow.add_edge(y, x + n, 1, inf - a[y][x]);
        }
    }

    let (max_flow, min_cost) = flow.flow(s, t, n as i64 * k);
    println!("{}", inf * max_flow as i64 - min_cost);

    let mut grid = vec![vec!['.'; n]; n];
    for edge in flow.edges() {
        if edge.to == t || edge.from == s {
            continue;
        }
        if edge.flow == 1 {
            let y = edge.from;
            let x = edge.to - n;
            grid[y][x] = 'X';
        }
    }

    for line in grid {
        for ch in line {
            print!("{}", ch);
        }
        println!("");
    }
}

