const INF: i64 = 1000000000;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let k: i64 = sc.read();
    let a: Vec<Vec<i64>> = (0..n).map(|_| sc.vec(n)).collect();

    let mut graph = MinCostFlowGraph::new(2 * n + 2);

    let source = 2 * n;
    let sink = 2 * n + 1;
    for i in 0..n {
        graph.add_edge(source, i, k, 0);
        graph.add_edge(n + i, sink, k, 0);
        graph.add_edge(i, sink, k, INF);
        for j in 0..n {
            graph.add_edge(i, n + j, 1, INF - a[i][j]);
        }
    }

    let (flow, cost) = graph.flow(source, sink, INF);
    assert_eq!(flow, k * (n as i64));

    let edges = graph.edges();
    let mut ans = vec![vec!['.'; n]; n];
    for edge in edges.into_iter() {
        if edge.from < n && edge.to < 2 * n && edge.flow == 1 {
            ans[edge.from][edge.to - n] = 'X';
        }
    }

