    let col = |j| n + j;
    let mut graph = MinCostFlowGraph::new(2 * n + 2);
    let source = 2 * n;
    let target = 2 * n + 1;

    for i in 0..n {
        for j in 0..n {
            graph.add_edge(col(j), row(i), 1, 10000000000 - a[i][j]);
