    #![allow(dead_code)]
    use std::{
        cmp::min, cmp::Reverse, collections::BinaryHeap, fmt::Debug, ops::Add, ops::AddAssign,
        ops::Mul, ops::Neg, ops::Sub, ops::SubAssign,
    };

    use num::{zero, Bounded, Zero};

    pub struct McfGraph<Cap, Cost> {
        n: usize,
        pos: Vec<(usize, usize)>, // "edge id" to "EdgeData" table. ( if edge id is `x`, "EdgeData" is g[pos[x].0][pos[x].1] )
        g: Vec<Vec<EdgeData<Cap, Cost>>>,
    }

    #[derive(Clone)]
    struct EdgeData<Cap, Cost> {
        to: usize,
        rev: usize,
        cap: Cap,
        cost: Cost,
    }
    pub struct Edge<Cap, Cost> {
        pub from: usize,
        pub to: usize,
        pub cap: Cap,
        pub flow: Cap,
        pub cost: Cost,
    }

    impl<
            Cap: Copy
                + AddAssign
                + Add<Output = Cap>
                + Bounded
                + PartialEq
                + Ord
                + Zero
                + Sub<Output = Cap>
                + SubAssign
                + Debug,
            Cost: Copy
                + Bounded
                + Ord
                + Zero
                + AddAssign
                + Sub<Output = Cost>
                + SubAssign
                + Mul<Cap, Output = Cost>
                + Neg<Output = Cost>
                + Debug,
        > McfGraph<Cap, Cost>
    {
        pub fn new(n: usize) -> Self {
            Self {
                n,
                pos: Vec::new(),
                g: vec![Vec::new(); n],
            }
        }
        pub fn add_edge(&mut self, from: usize, to: usize, cap: Cap, cost: Cost) -> usize {
            debug_assert!(from < self.n);
            debug_assert!(to < self.n);
            let m = self.pos.len();
            self.pos.push((from, self.g[from].len()));
            let from_id = self.g[from].len();
            let mut to_id = self.g[to].len();
            if from == to {
                to_id += 1;
            }
            self.g[from].push(EdgeData {
                to,
                rev: to_id,
                cap,
                cost,
            });
            self.g[to].push(EdgeData {
                to: from,
                rev: from_id,
                cap: zero(),
                cost: -cost,
            });
            m
        }

        pub fn get_edge(&self, i: usize) -> Edge<Cap, Cost> {
            let m = self.pos.len();
            debug_assert!(i < m);
            let e = &self.g[self.pos[i].0][self.pos[i].1];
            let re = &self.g[e.to][e.rev];
            Edge {
                from: self.pos[i].0,
                to: e.to,
                cap: e.cap + re.cap,
                flow: re.cap,
                cost: e.cost,
            }
        }
        pub fn edges(&self) -> Vec<Edge<Cap, Cost>> {
            (0..self.pos.len()).map(|i| self.get_edge(i)).collect()
        }
        pub fn flow(&mut self, s: usize, t: usize) -> (Cap, Cost) {
            self.flow_with_limit(s, t, Cap::max_value())
        }

        pub fn flow_with_limit(&mut self, s: usize, t: usize, flow_limit: Cap) -> (Cap, Cost) {
            self.slope_with_limit(s, t, flow_limit).pop().unwrap()
        }
        pub fn slope(&mut self, s: usize, t: usize) -> Vec<(Cap, Cost)> {
            self.slope_with_limit(s, t, Cap::max_value())
        }

        pub fn slope_with_limit(
            &mut self,
            s: usize,
            t: usize,
            flow_limit: Cap,
        ) -> Vec<(Cap, Cost)> {
            debug_assert!(s < self.n);
            debug_assert!(t < self.n);
            debug_assert!(s != t);
            let mut dual: Vec<Cost> = vec![zero(); self.n];
            let mut dist: Vec<Cost> = vec![zero(); self.n];
            let mut pv = vec![usize::max_value(); self.n];
            let mut pe = vec![usize::max_value(); self.n];
            let mut vis = vec![false; self.n];

            let mut flow = zero();
            let mut cost = zero();
            let mut prev_cost_per_flow = None;
            let mut result = Vec::new();
            result.push((flow, cost));
            while flow < flow_limit {
                if !self.dual_ref(s, t, &mut dist, &mut dual, &mut pv, &mut pe, &mut vis) {
                    break;
                }
                let mut c = flow_limit - flow;
                let mut v = t;
                while v != s {
                    c = min(c, self.g[pv[v]][pe[v]].cap);
                    v = pv[v];
                }
                let mut v = t;
                while v != s {
                    let e = &mut self.g[pv[v]][pe[v]];
                    e.cap -= c;
                    let e_rev = e.rev;
                    self.g[v][e_rev].cap += c;
                    v = pv[v];
                }
                let d = -dual[s];
                flow += c;
                cost += d * c;
                if prev_cost_per_flow == Some(d) {
                    result.pop();
                }
                result.push((flow, cost));
                prev_cost_per_flow = Some(d);
            }
            result
        }

        fn dual_ref(
            &mut self,
            s: usize,
            t: usize,
            dist: &mut Vec<Cost>,
            dual: &mut Vec<Cost>,
            pv: &mut Vec<usize>,
            pe: &mut Vec<usize>,
            vis: &mut Vec<bool>,
        ) -> bool {
            #[derive(Ord, PartialOrd, Eq, PartialEq)]
            struct Q<Cost> {
                key: Reverse<Cost>,
                to: usize,
            }
            for x in dist.iter_mut() {
                *x = Cost::max_value();
            }
            for x in pv.iter_mut() {
                *x = usize::max_value();
            }
            for x in pe.iter_mut() {
                *x = usize::max_value();
            }
            for x in vis.iter_mut() {
                *x = false;
            }
            let mut que = BinaryHeap::new();
            dist[s] = zero();
            que.push(Q {
                key: Reverse(zero()),
                to: s,
            });
            while let Some(Q { key: _, to: v }) = que.pop() {
                if vis[v] {
                    continue;
                }
                vis[v] = true;
                if v == t {
                    break;
                }
                for i in 0..self.g[v].len() {
                    let e = &self.g[v][i];
                    if vis[e.to] || e.cap == zero() {
                        continue;
                    }
                    let cost = e.cost - dual[e.to] + dual[v];
                    if dist[e.to] - dist[v] > cost {
                        dist[e.to] = dist[v] + cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        que.push(Q {
                            key: Reverse(dist[e.to]),
                            to: e.to,
                        });
                    }
                }
            }
            if !vis[t] {
                return false;
            }
            for v in 0..self.n {
                if !vis[v] {
                    continue;
                }
                dual[v] -= dist[t] - dist[v];
            }
            true
        }
    }
}

