const MAX_SCORE: i64 = 1e9 as i64;

fn main() {
    input! {
        n: usize, k: i64,
        table: [[i64; n]; n]
    };

    let mut flow = MinCostFlow::new(2*n+2);
    let source = 2*n;
    let sink = source+1;



    for i in 0..n {
        flow.add_edge(source, i, k, 0);
        flow.add_edge(n+i, sink, k, 0);
    }
    for i in 0..n {
        for j in 0..n {
            flow.add_edge(i, n+j, 1, MAX_SCORE-table[i][j]);
        }
    }
    flow.add_edge(source, sink, INF, MAX_SCORE);

    flow.min_cost_flow(source, sink, k*(n as i64));
    let mut ans_table = dvec!['.'; n, n];
    let mut best = 0;
    for i in 0..n {
        for &eidx in &flow.graph[i] {
            if flow.edges[eidx].cap == 0 && flow.edges[eidx].to < 2*n {
                let j = flow.edges[eidx].to-n;
                best += table[i][j];
                ans_table[i][j] = 'X';
            }
        }
    }

    println!("{}", best);
    for row in ans_table {
        println!("{}", join!(row, ""));
    }
}

use proconio::input;

fn main() {
    input! { n: usize, k: i64 }

    let mut g = MinCostFlow::new(n * 2 + 2);
    let s = n * 2;
    let t = s + 1;
    let kn = k * n as i64;
    const M: i64 = 1000000000;

    g.add_edge(s, t, kn, M);
    for i in 0..n {
        g.add_edge(s, i, k, 0);
        g.add_edge(i + n, t, k, 0);
        for j in 0..n {
            input!{ a: i64 }
            g.add_edge(i, j + n, 1, M - a);
        }
    }

    let v = kn * M - g.flow(s, t, kn);

    let mut f = vec![vec!['.'; n]; n];
    for i in 0..n {
        for &e in &g.edges[i] {
            if e.v == 0 && e.to < 2 * n {
                let j = e.to - n;
                f[i][j] = 'X';
            }
        }
    }

    println!("{}", v);
    println!("{}", f.iter()
        .map(|f| f.iter().collect())
        .collect::<Vec<String>>()
        .join("\n")
    );
}

use num::{Integer, Bounded, Signed, zero};
use std::ops::{AddAssign, SubAssign};

#[derive(Copy, Clone, Debug)]
struct Edge<T: Clone> {
    to: usize,
    rev: usize,
    v: T,
    cost: T,
}

struct MinCostFlow<T: Clone> {
    edges: Vec<Vec<Edge<T>>>,
}

impl<T: Copy + Clone + Integer + Bounded + Signed + AddAssign + SubAssign> MinCostFlow<T> {
    fn new(n: usize) -> Self {
        Self {
            edges: vec![vec![]; n],
        }
    }

    fn add_edge(&mut self, s: usize, t: usize, v: T, cost: T) {
        let sid = self.edges[s].len();
        let tid = self.edges[t].len();
        self.edges[s].push(Edge { to: t, rev: tid, v, cost });
        self.edges[t].push(Edge { to: s, rev: sid, v: zero(), cost: -cost });
    }

    fn flow(&mut self, s: usize, t: usize, mut flow: T) -> T {
        let n = self.edges.len();
        let mut ans = zero();
        let mut from = vec![(0, 0); n];

        while flow > zero() {
            let mut dist = vec![T::max_value(); n];
            let mut done = vec![false; n];

            dist[s] = zero();

            let mut q = std::collections::VecDeque::new();
            q.push_back(s);
            while let Some(s) = q.pop_front() {
                done[s] = false;
                for (i, &e) in self.edges[s].iter().enumerate() {
                    if e.v > zero() {
                        let cost = dist[s] + e.cost;
                        if cost < dist[e.to] {
                            dist[e.to] = cost;
                            from[e.to] = (s, i);
                            if !done[e.to] {
                                done[e.to] = true;
                                q.push_back(e.to);
                            }
                        }
                    }
                }
            }

            if dist[t] == T::max_value() {
                return dist[t];
            }

            let mut v = flow;
            let mut to = t;
            while to != s {
                let (f, i) = from[to];
                v = v.min(self.edges[f][i].v);
                to = f;
            }
            flow -= v;

            ans += dist[t] * v;
            let mut to = t;
            while to != s {
                let (f, i) = from[to];
                let edge = &mut self.edges[f][i];
                edge.v -= v;
                let rev = edge.rev;
                self.edges[to][rev].v += v;
                to = f;
            }
        }
        ans
    }
}

