const MAX_SCORE: i64 = 1e9 as i64;

fn main() {
    input! {
        n: usize, k: i64,
        table: [[i64; n]; n]
    };

    let mut flow = MinCostFlow::new(2*n+2);
    let source = 2*n;
    let sink = source+1;



    for i in 0..n {
        flow.add_edge(source, i, k, 0);
        flow.add_edge(n+i, sink, k, 0);
    }
    for i in 0..n {
        for j in 0..n {
            flow.add_edge(i, n+j, 1, MAX_SCORE-table[i][j]);
        }
    }
    let mut best = 0;
    let mut accumulated_cost = 0;
    let mut ans_table = dvec!['.'; n, n];
    for w in 1..=n*n {
        accumulated_cost += flow.min_cost_flow(source, sink, 1);
        let ans = (w as i64) * MAX_SCORE - accumulated_cost;
        if best < ans {
            best = ans;
            ans_table = dvec!['.'; n, n];
            for i in 0..n {
                for &eidx in &flow.graph[i] {
                    if flow.edges[eidx].cap == 0 && flow.edges[eidx].to < 2*n {
                        let j = flow.edges[eidx].to-n;
                        ans_table[i][j] = 'X';
                    }
                }
            }
        }
    }

    println!("{}", best);
    for row in ans_table {
        println!("{}", join!(row, ""));
    }
}

