pub mod ralgo {
    pub mod flow {
        use std::fmt::Display;
        use std::ops::{Add, AddAssign, Neg, Sub, SubAssign};

        pub trait Zero: Sized {
            fn zero() -> Self;
        }

        pub trait One: Sized {
            fn one() -> Self;
        }

        pub trait Cost:
        Display
        + Copy
        + Eq
        + Ord
        + Zero
        + One
        + Add<Output = Self>
        + AddAssign
        + Sub<Output = Self>
        + Neg<Output = Self>
        {
            fn is_zero(&self) -> bool {
                self == &Self::zero()
            }
            fn is_positive(&self) -> bool {
                self > &Self::zero()
            }
            fn is_negative(&self) -> bool {
                self < &Self::zero()
            }
        }

        pub trait Flow:
        Display
        + Copy
        + Eq
        + Ord
        + Zero
        + One
        + Add<Output = Self>
        + AddAssign
        + Sub<Output = Self>
        + SubAssign
        + Neg<Output = Self>
        {
            fn is_zero(&self) -> bool {
                self == &Self::zero()
            }
            fn is_positive(&self) -> bool {
                self > &Self::zero()
            }
            fn is_negative(&self) -> bool {
                self < &Self::zero()
            }
            fn abs(&self) -> Self {
                if self.is_negative() {
                    -*self
                } else {
                    *self
                }
            }
        }

        macro_rules! implement {
            ($T:ty) => {
                impl Zero for $T {
                    #[inline]
                    fn zero() -> Self {
                        0
                    }
                }
                impl One for $T {
                    #[inline]
                    fn one() -> Self {
                        1
                    }
                }
                impl Flow for $T {}
                impl Cost for $T {}
            };
        }

        implement!(i8);
        implement!(i16);
        implement!(i32);
        implement!(i64);
        implement!(i128);
        implement!(isize);

        pub mod network_simplex {
            use super::{Cost, Flow, Zero};
            use core::mem;
            use std::cmp::{max, min};
            use std::collections::HashSet;
            use std::ops::{Add, Mul};
            use std::option::Option::{None, Some};

            struct Edge<F, C> {
                src: usize,
                dst: usize,
                flow: F,
                capacity: F,
                cost: C,
            }

            #[derive(Copy, Clone, Ord, PartialOrd, Eq, PartialEq, Debug, Hash)]
            pub struct EdgeId(usize);
            impl EdgeId {
                fn rev(&self) -> Self {
                    EdgeId(self.0 ^ 1)
                }
            }

            struct VertexData<C> {
                potential: C,
                adjacent_edges: Vec<EdgeId>,
                parent: Option<usize>,
                parent_edge: Option<EdgeId>, // out-tree, i.e. this node == e.src
                depth: usize,
                tree_edges: HashSet<EdgeId>,
            }
            impl<C: Zero> Default for VertexData<C> {
                fn default() -> Self {
                    Self {
                        potential: C::zero(),
                        adjacent_edges: Vec::new(),
                        parent: None,
                        parent_edge: None,
                        depth: 0,
                        tree_edges: HashSet::new(),
                    }
                }
            }
            pub struct NetworkSimplex<F: Flow, C: Cost> {
                edges: Vec<Edge<F, C>>,
                balances: Vec<F>,
            }
            struct TemporaryData<C: Cost> {
                vertices: Vec<VertexData<C>>,
                n: usize,
                root: usize,
                block_size: usize,
                next_scan_start: usize,
            }

            pub struct Ret<F, C> {
                edges: Vec<(F, C)>,
                potential: Vec<C>,
            }
            impl<F: Flow, C: Cost> Ret<F, C> {
                pub fn get_value<T>(&self) -> T
                    where
                        T: From<F> + From<C> + Mul<Output = T> + Add<Output = T> + Zero,
                {
                    self.edges
                        .iter()
                        .filter(|(f, _)| f.is_positive())
                        .map(|(f, c)| T::from(*f) * T::from(*c))
                        .fold(T::zero(), |a, b| a + b)
                }
                pub fn get_flow(&self, e: &EdgeId) -> F {
                    self.edges[e.0].0
                }
                pub fn get_potential(&self, v: usize) -> C {
                    self.potential[v]
                }
            }

            impl<F: Flow, C: Cost> NetworkSimplex<F, C> {
                pub fn new() -> Self {
                    Self {
                        edges: Vec::new(),
                        balances: Vec::new(),
