const MOD: u32 = 1_000_000_007;
const INF:usize=1usize<<60;
const_mod!(P,MOD);

fn main(){
    input!{
        n:usize,k:usize,
        v:[[i64;n];n]
    }
    let mut mcf=MinCostFlow::new(n*n+2*n+2);
    for i in 0..n{
        mcf.add_edge(n*n+2*n, n*n+i, k as i64, 0);
        mcf.add_edge(n*n+n+i, n*n+2*n+1, k as i64, 0);
        for j in 0..n{
            mcf.add_edge(n*n+i,n*i+j, 1, -v[i][j]);
            mcf.add_edge(n*i+j,n*n+n+j, 1, 0);
        }
    }
    mcf.add_edge(n*n+2*n,n*n+2*n+1,INF as i64, 0);
    println!("{}",-mcf.run(n*n+2*n,n*n+2*n+1,(k*n) as i64));
    let mut ans=vec![vec!['.';n];n];
    for i in 0..n{
        for j in 0..mcf.e[n*n+i].len(){
            let ed=mcf.e[n*n+i][j];
            if ed.to-n*i<n&&ed.is_rev{
                if ed.cap==0{
                    ans[i][ed.to-n*i]='X';
                }
            }
        }
    }
    for e in ans{
        println!("{}",e.iter().collect::<String>());
    }
}




