        }
    }
    pub fn add_edge(&mut self,from:usize,to:usize,cap:i64,cost:i64){
        if cost>=0{
            {
                let tmp=Edge{
                    to:to,
                    cap:cap,
                    cost:cost*(self.v as i64),
                    rev:self.e[to].len(),
                    is_rev:false,
                };
                self.e[from].push(tmp);
            }
            {
                let tmp=Edge{
                    to:from,
                    cap:0,
                    cost:-cost*(self.v as i64),
                    rev:self.e[from].len()-1,
                    is_rev:true,
                };
                self.e[to].push(tmp);
            }
        }else{
            {
                let tmp=Edge{
                    to:to,
                    cap:0,
                    cost:cost*(self.v as i64),
                    rev:self.e[to].len(),
                    is_rev:true,
                };
                self.e[from].push(tmp);
            }
            {
                let tmp=Edge{
                    to:from,
                    cap:cap,
                    cost:-cost*(self.v as i64),
                    rev:self.e[from].len()-1,
                    is_rev:false,
                };
                self.e[to].push(tmp);
            }
            self.ans+=cap*cost;
            self.d[from]-=cap;
            self.d[to]+=cap;
        }
    }
    pub fn flow(&mut self)->i64{
        let mut p=vec![0i64;self.v];
        while self.eps!=1{
            self.eps>>=1;
            for i in 0..self.v{
                for j in 0..self.e[i].len(){
                    let ed=self.e[i][j];
                    if ed.is_rev{
                        continue;
                    }
                    if ed.cost-p[i]+p[ed.to]<0{
                        let f=ed.cap;
                        self.e[i][j].cap-=f;
                        self.d[i]-=f;
                        self.d[ed.to]+=f;
                        self.e[ed.to][ed.rev].cap+=f;
                    }
                    if ed.cost-p[i]+p[ed.to]>0{
                        let f=-self.e[ed.to][ed.rev].cap;
                        self.e[i][j].cap-=f;
                        self.d[i]-=f;
                        self.d[ed.to]+=f;
                        self.e[ed.to][ed.rev].cap+=f;
                    }
                }
            }
            for i in 0..self.v{
                if self.d[i]>0{
                    self.active.push_back(i);
                }
            }
            while !self.active.is_empty(){
                let node=self.active.pop_front().unwrap();
                if self.d[node]<=0{continue;}
                let mut b=false;
                for j in 0..self.e[node].len(){
                    let ed=self.e[node][j];
                    if self.d[node]==0{break;}
                    if -self.eps<=ed.cost-p[node]+p[ed.to]&&ed.cost-p[node]+p[ed.to]<0{
                        let f=min(self.d[node],ed.cap);
                        if f==0{continue;}
                        self.e[node][j].cap-=f;
                        self.d[node]-=f;
                        self.d[ed.to]+=f;
                        self.e[ed.to][ed.rev].cap+=f;
                        if self.d[ed.to]>0{
                            self.active.push_back(ed.to);
                        }
                        b=true;
                    }
                }
                if self.d[node]>0{self.active.push_back(node);}
                if !b{p[node]+=self.eps;}
            }
        }
        for i in 0..self.v{
            for j in 0..self.e[i].len(){
                let ed=self.e[i][j];
                if ed.is_rev{continue;}
                self.ans+=self.e[ed.to][ed.rev].cap*ed.cost/(self.v as i64);
            }
        }
        self.ans
    }
    pub fn run(&mut self,s:usize,t:usize,f:i64)->i64{
        self.d[s]+=f;
        self.d[t]-=f;
        self.flow()
    }

}

}  // mod min_cost_flow

